import cp from 'child_process'
import * as fs from 'fs/promises'
import * as path from 'path'
import * as os from 'os'
import * as axios from 'axios'
import * as vscode from 'vscode'
import {Inject} from '@nestjs/common'
import {Utils} from '../utils/utils'
import {
  EXTENSION_CONTEXT_TOKEN,
  PRIMARY_OUTPUT_CHANNEL_TOKEN,
} from '../custom-providers'
import {
  SettingName,
  getExtensionSetting,
  settingModifyPrompt,
} from '../utils/settings'

export const INSTALL_BSP_COMMAND = 'bazelbsp.install'

const MAVEN_PACKAGE = 'org.virtuslab:bazel-bsp'
const INSTALL_METHOD = 'org.jetbrains.bsp.bazel.install.Install'
const COURSIER_URL_DEFAULT = 'https://git.io/coursier-cli'
const COURSIER_URL_APPLE_SILICON =
  'https://github.com/coursier/coursier/releases/latest/download/cs-aarch64-apple-darwin.gz'
const COURSIER_URL_APPLE_INTEL =
  'https://github.com/coursier/launchers/raw/master/cs-x86_64-apple-darwin.gz'
const OPEN_JDK_JAVA_17 = 'openjdk:1.17.0'
const TEMURIN_JAVA_17 = 'temurin:1.17.0.0'

export interface InstallConfig {
  bazelProjectFilePath: string
  serverVersion: string
  bazelBinaryPath: string
  projectViewScopeDirectory?: string
}

export class BazelBSPInstaller {
  @Inject(PRIMARY_OUTPUT_CHANNEL_TOKEN)
  private readonly outputChannel: vscode.OutputChannel
  @Inject(EXTENSION_CONTEXT_TOKEN) private readonly ctx: vscode.ExtensionContext

  onModuleInit() {
    this.ctx.subscriptions.push(
      vscode.commands.registerCommand(
        INSTALL_BSP_COMMAND,
        this.install.bind(this)
      )
    )
  }

  /**
   * Installs Bazel BSP at the root of the current repository.
   * This will ensure that the BSP server is in place and available to be launched in this workspace.
   * See more: https://github.com/JetBrains/bazel-bsp/tree/master/install
   * @returns Boolean indicating a successful installation.
   */
  public async install(): Promise<boolean> {
    // Install at the git root of the current workspace.
    const root = await Utils.getWorkspaceGitRoot()
    if (!root) {
      return false
    }

    const installMode = getExtensionSetting(SettingName.SERVER_INSTALL_MODE)
    if (installMode === 'Prompt') {
      // User prompt before proceeding.
      const installSelection: vscode.MessageItem = {title: 'Install BSP'}
      const userSelection =
        await vscode.window.showErrorMessage<vscode.MessageItem>(
          `Do you want to install the Bazel Build Server in ${root}?`,
          installSelection,
          {title: 'Cancel', isCloseAffordance: true}
        )

      if (userSelection?.title !== installSelection.title) {
        this.outputChannel.appendLine(
          `Installation in ${root} declined by user`
        )
        return false
      }
    } else if (installMode !== 'Auto') {
      // Installation is disabled by setting.
      this.outputChannel.appendLine(
        `Installation in ${root} skipped because '${SettingName.SERVER_INSTALL_MODE}' setting is set to ${installMode}`
      )
      return false
    }

    const installConfig = await this.getInstallConfig(root)
    if (!installConfig) {
      this.outputChannel.appendLine(
        'Installation interrupted: failed to get settings.'
      )
      this.outputChannel.show()
      return false
    }
    this.outputChannel.appendLine(`Installing Bazel BSP server at ${root}`)

    // Coursier install, to avoid dependence on the local environment.
    const coursierPath = await this.downloadCoursier()
    if (coursierPath === undefined) {
      return false
    }

    // Execute the BSP installer within this workspace.
    const exitCode = await this.runInstaller(coursierPath, root, installConfig)
    if (exitCode !== 0) {
      this.outputChannel.appendLine(
        'Bazel BSP installation failed. Please see output above for details.'
      )
      this.outputChannel.show()
      return false
    }

    // Temporary: Patch the python_info file to be compatible with rules_py.
    await this.patchPythonAspect(root)
    return true
  }

  /**
   * Downloads the Coursier cli to a temporary location, for one-time use by this installer.
   * This avoids depending on the local environment to have an existing available installation.
   * @returns The path to the downloaded Coursier cli, or undefined if the download failed.
   */
  private async downloadCoursier(): Promise<string | undefined> {
    const tempDir = await fs.mkdtemp(path.join(os.tmpdir(), 'coursier-'))
    const coursierPath = path.join(tempDir, 'coursier')

    let coursierUrl: string
    coursierUrl =
      os.platform() === 'darwin'
        ? os.arch() === 'arm64'
          ? COURSIER_URL_APPLE_SILICON
          : COURSIER_URL_APPLE_INTEL
        : COURSIER_URL_DEFAULT

    this.outputChannel.appendLine(`Downloading Coursier from ${coursierUrl}`)

    try {
      const response = await axios.default.get(coursierUrl, {
        responseType: 'arraybuffer',
      })

      let fileData = response.data

      // Decompress if downloading a gzipped file
      if (coursierUrl.endsWith('.gz')) {
        this.outputChannel.appendLine('Using gzipped Coursier')
        fileData = await Utils.gunzip(fileData)
      }

      await fs.writeFile(coursierPath, fileData)
      await fs.chmod(coursierPath, 0o755)
    } catch (e) {
      this.outputChannel.appendLine(`Failed to download Coursier: ${e}`)
      return undefined
    }

    this.outputChannel.appendLine(
      `Coursier temporarily installed at ${coursierPath}`
    )
    return coursierPath
  }

  /**
   * Run the BSP installer using the downloaded Coursier cli.
   * @param coursierPath Absolute path to an executable copy of the Coursier cli.
   * @param root Root of the repository where the BSP server will be installed.
   * @returns The exit code of the installer process, or null if the process failed to start.
   */
  private async runInstaller(
    coursierPath: string,
    root: string,
    config: InstallConfig
  ): Promise<number | null> {
    this.outputChannel.appendLine(
      `Launching Bazel BSP installer from Maven package: ${MAVEN_PACKAGE}`
    )
    const bazelPath = path.join(root, config.bazelBinaryPath)

    // Flags to be passed to the installer.
    // See CliOptionsProvider in the server code for available options.
    const installFlags: Map<string, string> = new Map([
      // Set Bazel project details to be used if a project file is not already present.
      ['--project-view-file', config.bazelProjectFilePath],
      ['--bazel-binary', bazelPath],
    ])
    const installFlagSwitches: string[] = []
    if (config.projectViewScopeDirectory) {
      installFlags.set('--directories', config.projectViewScopeDirectory)
      installFlagSwitches.push('--derive-targets-from-directories')
    } else {
      installFlags.set('--targets', '//your/targets/here/...')
    }

    const flagsString = [
      ...Array.from(installFlags.entries()).map(
        ([key, value]) => `${key} "${value}"`
      ),
      ...installFlagSwitches,
    ].join(' ')
    const additionalInstallFlags = getExtensionSetting(
      SettingName.ADDITIONAL_INSTALL_FLAGS
    )
    const additionalInstallFlagsString = additionalInstallFlags
      ? additionalInstallFlags.join(' ')
      : ''

    const javaVersion =
      os.platform() === 'darwin' ? TEMURIN_JAVA_17 : OPEN_JDK_JAVA_17
    this.outputChannel.appendLine(`Using Java version: ${javaVersion}`)
    const installCommand = `"${coursierPath}" launch --jvm ${javaVersion} ${MAVEN_PACKAGE}:${config.serverVersion} -M ${INSTALL_METHOD} ${additionalInstallFlagsString} -- ${flagsString}`
    this.outputChannel.appendLine(`Running command: ${installCommand}`)

    // Report progress in output channel.
    const installProcess = cp.spawn(installCommand, {cwd: root, shell: true})
    installProcess.stdout?.on('data', chunk => {
      this.outputChannel.appendLine(chunk.toString())
    })
    installProcess.stderr?.on('data', chunk => {
      this.outputChannel.appendLine(chunk.toString())
    })
    return new Promise<number | null>(resolve => {
      // Handle cases where process is already exited (e.g. tests), or exits later on.
      if (installProcess.exitCode !== null) resolve(installProcess.exitCode)
      installProcess.on('exit', code => {
        resolve(code)
      })

      // Handle cases where the process fails to start.
      installProcess.on('error', err => {
        this.outputChannel.appendLine(`Failed to start installer: ${err}`)
        resolve(null)
      })
    })
  }

  private async getInstallConfig(root: string): Promise<InstallConfig | null> {
    const settingError = (setting: SettingName) => {
      this.outputChannel.appendLine(
        `Install interrupted. Please check the ${setting} setting to ensure a valid value.`
      )
    }
    const projectFilePath = getExtensionSetting(
      SettingName.BAZEL_PROJECT_FILE_PATH
    )
    if (projectFilePath === undefined) {
      settingModifyPrompt(
        'Unable to determine the Bazel project file path from settings.',
        SettingName.BAZEL_PROJECT_FILE_PATH
      )
      settingError(SettingName.BAZEL_PROJECT_FILE_PATH)
      return null
    }

    const bazelBspVersion = getExtensionSetting(SettingName.BSP_SERVER_VERSION)
    if (bazelBspVersion === undefined) {
      settingModifyPrompt(
        'Unable to determine the Bazel BSP version from settings.',
        SettingName.BSP_SERVER_VERSION
      )
      settingError(SettingName.BSP_SERVER_VERSION)
      return null
    }

    const bazelBinaryPath = getExtensionSetting(SettingName.BAZEL_BINARY_PATH)
    if (bazelBinaryPath === undefined) {
      settingModifyPrompt(
        'Unable to determine the Bazel BSP binary path from settings.',
        SettingName.BAZEL_BINARY_PATH
      )
      settingError(SettingName.BAZEL_BINARY_PATH)
      return null
    }

    return {
      bazelProjectFilePath: projectFilePath,
      serverVersion: bazelBspVersion,
      bazelBinaryPath: bazelBinaryPath,
      projectViewScopeDirectory: this.getProjectViewScopeDirectory(
        root,
        getExtensionSetting(SettingName.PROJECT_VIEW_SCOPE_DIRECTORY_MIN_DEPTH)
      ),
    }
  }

  private getProjectViewScopeDirectory(
    root: string,
    minDepth: number | null | undefined
  ): string | undefined {
    if (minDepth === undefined || minDepth === null || minDepth < 1) {
      return undefined
    }

    const workspaceRoot = Utils.getWorkspaceRoot()
    if (!workspaceRoot) {
      return undefined
    }

    const relativePath = path.relative(root, workspaceRoot.fsPath)
    if (
      relativePath === '' ||
      relativePath.startsWith('..') ||
      path.isAbsolute(relativePath)
    ) {
      return undefined
    }

    const pathSegments = relativePath.split(path.sep).filter(Boolean)
    if (pathSegments.length < minDepth) {
      return undefined
    }

    return pathSegments.join('/')
  }

  /**
   * Temporary solution to ensure that the rules_python load statement is always included in the Python aspect.
   * This is needed for compatibility with targets that no longer include the builtin Python providers (e.g. rules_py).
   * This will be addressed by https://github.com/JetBrains/hirschgarten/pull/210 once we have a standalone version of the server back in place.
   * @param root
   */
  private async patchPythonAspect(root: string) {
    // Get the current contents of the Python aspect template, as added by the installer.
    const targetFile = path.join(
      root,
      '.bazelbsp/aspects/rules/python/python_info.bzl.template'
    )

    let content = ''
    try {
      content = await fs.readFile(targetFile, 'utf8')
    } catch {
      this.outputChannel.appendLine(
        `Failed to read file ${targetFile}. Skipping patch.`
      )
    }

    // Make rules_python load statement non-conditional for compatibility with rules_py.
    const regex =
      /#if\( \$pythonEnabled == "true" && \$bazel8OrAbove == "true" \)[\s\S]*?#end/
    const replacement =
      'load("@rules_python//python:defs.bzl", "PyInfo", "PyRuntimeInfo")'

    // Replace the matched block with the replacement.
    content = content.replace(regex, replacement)
    try {
      await fs.writeFile(targetFile, content, 'utf8')
    } catch (err) {
      this.outputChannel.appendLine(
        `Failed to write updated Python aspect to ${targetFile}. Skipping patch.`
      )
    }
  }
}

import * as path from 'path'

import {runTests} from '@vscode/test-electron'
import {randomBytes} from 'crypto'
import {tmpdir} from 'os'
import {join} from 'path'
import {mkdir} from 'fs'
import {promisify} from 'util'
const mkdirAsync = promisify(mkdir)

async function main(): Promise<void> {
  try {
    const extensionDevelopmentPath = path.resolve(__dirname, '../../')
    const extensionTestsPath = path.resolve(__dirname, './suite/index')

    const testTmp = await getTempDir()

    // Download VS Code, unzip it and run the integration test
    await runTests({
      extensionDevelopmentPath,
      extensionTestsPath,
      launchArgs: [testTmp],
      extensionTestsEnv: {
        DEVPOD_FLAVOR: 'go',
        WORKSPACE_ROOT: testTmp,
      },
    })
  } catch (err) {
    console.error('Failed to run tests')
    process.exit(1)
  }
}

async function getTempDir(): Promise<string> {
  const rng = randomBytes(16).toString('hex')
  const temp = join(tmpdir(), rng)
  await mkdirAsync(temp, {recursive: true})

  return temp
}

main()
  .then(() => {})
  .catch(e => {
    console.error(e)
  })

import * as vscode from 'vscode'
import {Inject, Injectable, OnModuleInit} from '@nestjs/common'

import * as bsp from '../bsp/bsp'
import * as bspExt from '../bsp/bsp-ext'
import {BuildServerManager} from '../server/server-manager'
import {EXTENSION_CONTEXT_TOKEN} from '../custom-providers'
import {Deferred, Utils} from '../utils/utils'
const pkg = require('../../package.json')

const SUPPORTED_LANGUAGES = ['java', 'scala', 'kotlin', 'python', 'typescript']

/**
 * To intercept notifications from a specific originId, define custom handlers using this interface.
 * Use registerOriginHandlers and disposeOriginHandlers to manage their lifecycle.
 */
export type TaskOriginHandlers = {
  onBuildLogMessage?: (params: bsp.LogMessageParams) => void
  onBuildTaskStart?: (params: bsp.TaskStartParams) => void
  onBuildTaskProgress?: (params: bsp.TaskProgressParams) => void
  onBuildTaskFinish?: (params: bsp.TaskFinishParams) => void
  onBuildPublishOutput?: (params: bspExt.PublishOutputParams) => void
}

@Injectable()
export class BazelBSPBuildClient
  implements
    bsp.BuildClient,
    bspExt.ExtendedBuildClient,
    OnModuleInit,
    vscode.Disposable
{
  @Inject(EXTENSION_CONTEXT_TOKEN) private readonly ctx: vscode.ExtensionContext
  @Inject(BuildServerManager) private readonly buildServer: BuildServerManager

  private initializeResult: Deferred<bsp.InitializeBuildResult> = new Deferred()
  private clientOutputChannel: vscode.LogOutputChannel =
    vscode.window.createOutputChannel('Bazel BSP (client)', {log: true})
  private originHandlers: Map<string, TaskOriginHandlers> = new Map()

  async onModuleInit() {
    this.ctx.subscriptions.push(this)
    this.ctx.subscriptions.push(this.clientOutputChannel)

    this.ctx.subscriptions.push(
      vscode.commands.registerCommand('bazelbsp.showServerOutput', () => {
        this.clientOutputChannel.show()
      })
    )

    const conn = await this.buildServer.getConnection()
    bsp.registerBuildClientHandlers(conn, this)
    bspExt.registerExtendedBuildClientHandlers(conn, this)
    this.initializationRequest()
  }

  async dispose() {}

  getInitializeResult(): Promise<bsp.InitializeBuildResult> {
    return this.initializeResult.promise
  }

  /**
   * Register a TaskOriginHandlers implementation to be used for all notifications that match the originId.
   * Notifications will be redirected to the corresponding method of the registered handler.
   * If a method is unset, default behavior defined in the build client will be used.
   * @param originId value for which the registered handlers will be used.
   * @param handlers implementation that will be used instead of the default behavior.
   */
  registerOriginHandlers(originId: string, handlers: TaskOriginHandlers): void {
    this.originHandlers.set(originId, handlers)
  }

  /**
   * Clean up handlers for a given originId.
   * @param originId value for which the registered handlers will be removed.
   */
  disposeOriginHandlers(originId: string): void {
    this.originHandlers.delete(originId)
  }

  onBuildShowMessage(params: bsp.ShowMessageParams): void {
    switch (params.type) {
      case bsp.MessageType.Error:
        vscode.window.showErrorMessage(params.message)
        break
      case bsp.MessageType.Warning:
        vscode.window.showWarningMessage(params.message)
        break
      case bsp.MessageType.Info:
        vscode.window.showInformationMessage(params.message)
        break
      case bsp.MessageType.Log:
        this.clientOutputChannel.info(params.message)
        break
    }
  }

  onBuildLogMessage(params: bsp.LogMessageParams): void {
    if (params.originId) {
      // Intercept if a custom handler is registered for this origidId and method.
      const handler = this.originHandlers.get(params.originId)
      if (handler && handler.onBuildLogMessage) {
        handler.onBuildLogMessage(params)
        return
      }
    }

    // Use "Developer -> Set log level..." to control the level of logging that will be displayed.
    const message = Utils.removeAnsiEscapeCodes(params.message)
    switch (params.type) {
      case bsp.MessageType.Error:
        this.clientOutputChannel.error(message)
        break
      case bsp.MessageType.Warning:
        this.clientOutputChannel.warn(message)
        break
      case bsp.MessageType.Info:
      case bsp.MessageType.Log:
      default:
        this.clientOutputChannel.info(message)
        break
    }
  }

  onBuildPublishDiagnostics(params: bsp.PublishDiagnosticsParams): void {
    this.clientOutputChannel.trace(JSON.stringify(params))
  }

  onBuildTargetDidChange(params: bsp.DidChangeBuildTarget): void {
    this.clientOutputChannel.trace(JSON.stringify(params))
  }

  onBuildTaskStart(params: bsp.TaskStartParams): void {
    if (params.originId) {
      // Intercept if a custom handler is registered for this origidId and method.
      const handler = this.originHandlers.get(params.originId)
      if (handler && handler.onBuildTaskStart) {
        handler.onBuildTaskStart(params)
        return
      }
    }

    this.clientOutputChannel.trace(JSON.stringify(params))
  }

  onBuildTaskProgress(params: bsp.TaskProgressParams): void {
    if (params.originId) {
      // Intercept if a custom handler is registered for this origidId and method.
      const handler = this.originHandlers.get(params.originId)
      if (handler && handler.onBuildTaskProgress) {
        handler.onBuildTaskProgress(params)
        return
      }
    }

    this.clientOutputChannel.trace(JSON.stringify(params))
  }

  onBuildTaskFinish(params: bsp.TaskFinishParams): void {
    if (params.originId) {
      // Intercept if a custom handler is registered for this origidId and method.
      const handler = this.originHandlers.get(params.originId)
      if (handler && handler.onBuildTaskFinish) {
        handler.onBuildTaskFinish(params)
        return
      }
    }

    this.clientOutputChannel.trace(JSON.stringify(params))
  }

  onBuildPublishOutput(params: bspExt.PublishOutputParams): void {
    if (params.originId) {
      // Intercept if a custom handler is registered for this origidId and method.
      const handler = this.originHandlers.get(params.originId)
      if (handler && handler.onBuildPublishOutput) {
        handler.onBuildPublishOutput(params)
        return
      }
    }

    this.clientOutputChannel.trace(JSON.stringify(params))
  }

  onRunPrintStdout(params: bsp.PrintParams): void {
    this.clientOutputChannel.trace(JSON.stringify(params))
  }

  onRunPrintStderr(params: bsp.PrintParams): void {
    this.clientOutputChannel.trace(JSON.stringify(params))
  }

  private async initializationRequest() {
    // Wait for build server connection readiness.
    const conn = await this.buildServer.getConnection()

    // Send initialize request to the server.
    try {
      const rootUri = Utils.getWorkspaceRoot()
      const initData: bspExt.InitializeBuildData = {
        featureFlags: {
          isPythonSupportEnabled: true,
        },
      }
      const initResult = await conn.sendRequest(bsp.BuildInitialize.type, {
        displayName: 'VS Code Bazel BSP',
        version: pkg.version,
        bspVersion: bsp.Bsp4Ts.ProtocolVersion,
        rootUri: rootUri?.toString() ?? '',
        capabilities: {
          languageIds: SUPPORTED_LANGUAGES,
        },
        data: initData,
      })

      // Notify the build server that client initialization is complete.
      await conn.sendNotification(bsp.OnBuildInitialized.type)
      this.initializeResult.resolve(initResult)
    } catch (e) {
      this.initializeResult.reject(e)
    }
  }
}

import {randomUUID} from 'crypto'
import {CancellationToken, TestRunRequest} from 'vscode'
import {Inject, Injectable} from '@nestjs/common'

import {TestCaseStore} from '../test-explorer/store'
import {TestRunTracker} from './run-tracker'
import {BazelBSPBuildClient} from '../test-explorer/client'
import {CoverageTracker} from '../coverage-utils/coverage-tracker'
import {LanguageToolManager} from '../language-tools/manager'
import {detectIdeClient} from '../utils/utils'

@Injectable()
export class RunTrackerFactory {
  @Inject(TestCaseStore) private readonly testCaseStore: TestCaseStore
  @Inject(BazelBSPBuildClient) private readonly buildClient: BazelBSPBuildClient
  @Inject(CoverageTracker) private readonly coverageTracker: CoverageTracker
  @Inject(LanguageToolManager)
  private readonly languageToolManager: LanguageToolManager

  /**
   * Creates a new test run tracker, and register it with the build client.
   * @param request The test run request which will be used to populate a TestRunTracker.
   * @returns TestRunTracker populated for this run.
   */
  public newRun(
    request: TestRunRequest,
    cancelToken: [REDACTED]
  ): TestRunTracker {
    const originId = randomUUID()
    const run = this.testCaseStore.testController.createTestRun(request)
    const requestTracker = new TestRunTracker({
      testCaseMetadata: this.testCaseStore.testCaseMetadata,
      run: run,
      request: request,
      originName: originId,
      cancelToken: cancelToken,
      coverageTracker: this.coverageTracker,
      languageToolManager: this.languageToolManager,
    })

    const ideClient = detectIdeClient()
    requestTracker.setIdeTag(ideClient)

    this.buildClient.registerOriginHandlers(originId, requestTracker)
    requestTracker.onDone(() =>
      this.buildClient.disposeOriginHandlers(originId)
    )
    return requestTracker
  }
}

import * as vscode from 'vscode'
import {Inject, Injectable, OnModuleInit} from '@nestjs/common'

import {TestCaseStore} from '../test-explorer/store'
import {BazelBSPBuildClient} from '../test-explorer/client'
import {BuildServerManager, CANCEL_ERROR_CODE} from '../server/server-manager'
import {EXTENSION_CONTEXT_TOKEN} from '../custom-providers'
import * as bsp from '../bsp/bsp'
import {TestCaseStatus} from './run-tracker'
import {MessageConnection} from 'vscode-jsonrpc'
import {TestRunTracker} from './run-tracker'
import {RunTrackerFactory} from './run-factory'
import {CoverageTracker} from '../coverage-utils/coverage-tracker'
import {getExtensionSetting, SettingName} from '../utils/settings'

@Injectable()
export class TestRunner implements OnModuleInit, vscode.Disposable {
  @Inject(EXTENSION_CONTEXT_TOKEN) private readonly ctx: vscode.ExtensionContext
  @Inject(TestCaseStore) private readonly testCaseStore: TestCaseStore
  @Inject(BazelBSPBuildClient) private readonly buildClient: BazelBSPBuildClient
  @Inject(BuildServerManager) private readonly buildServer: BuildServerManager
  @Inject(RunTrackerFactory) private readonly runFactory: RunTrackerFactory
  @Inject(CoverageTracker) private readonly coverageTracker: CoverageTracker

  runProfiles: Map<vscode.TestRunProfileKind, vscode.TestRunProfile>

  onModuleInit() {
    this.ctx.subscriptions.push(this)
    this.setupRunProfiles()
  }

  dispose() {}

  private setupRunProfiles() {
    this.runProfiles = new Map()

    // Main run profile
    const mainRunProfile = this.testCaseStore.testController.createRunProfile(
      'Run',
      vscode.TestRunProfileKind.Run,
      this.runHandler.bind(this)
    )
    this.ctx.subscriptions.push(mainRunProfile)
    this.runProfiles.set(vscode.TestRunProfileKind.Run, mainRunProfile)

    // Coverage run profile
    const coverageRunProfile =
      this.testCaseStore.testController.createRunProfile(
        'Run with Coverage',
        vscode.TestRunProfileKind.Coverage,
        this.runHandler.bind(this)
      )
    this.ctx.subscriptions.push(coverageRunProfile)
    this.runProfiles.set(vscode.TestRunProfileKind.Coverage, coverageRunProfile)
    coverageRunProfile.loadDetailedCoverage =
      this.coverageTracker.loadDetailedCoverage.bind(this.coverageTracker)

    // Debug run profile, added only when enabled.
    if (getExtensionSetting(SettingName.DEBUG_ENABLED)) {
      const debugRunProfile =
        this.testCaseStore.testController.createRunProfile(
          'Run with Debug',
          vscode.TestRunProfileKind.Debug,
          this.runHandler.bind(this)
        )
      this.runProfiles.set(vscode.TestRunProfileKind.Debug, debugRunProfile)
    }
  }

  private async runHandler(
    request: vscode.TestRunRequest,
    cancelToken: [REDACTED]
  ) {
    const conn = await this.buildServer.getConnection()
    const requestTracker = this.runFactory.newRun(request, cancelToken)

    await requestTracker.executeRun(async (item, cancelToken) => {
      await this.runTestCase(item, requestTracker, conn, cancelToken)
    })
  }

  private async runTestCase(
    item: vscode.TestItem,
    runTracker: TestRunTracker,
    conn: MessageConnection,
    cancelToken: [REDACTED]
  ) {
    const testInfo = this.testCaseStore.testCaseMetadata.get(item)
    if (!testInfo) return
    const params = testInfo.prepareTestRunParams(runTracker)
    if (params === undefined) {
      return
    }

    let result: bsp.TestResult | undefined
    try {
      result = await conn.sendRequest(
        bsp.BuildTargetTest.type,
        params,
        cancelToken
      )
    } catch (e) {
      if (e.code === CANCEL_ERROR_CODE) {
        runTracker.updateStatus(
          item,
          TestCaseStatus.Errored,
          new vscode.TestMessage(
            `Testing canceled by user during run of ${item.label}.`
          )
        )
        return
      } else {
        throw e
      }
    }

    if (result) testInfo.processTestRunResult(runTracker, result)
  }
}

import {
  TaskStartParams,
  TaskFinishParams,
  TaskId,
  BuildTargetIdentifier,
  TaskStartDataKind,
  TestTask,
} from '../bsp/bsp'

export type TaskEventCollector = {
  startParams: TaskStartParams
  parents: TaskEventCollector[]
  finishParams?: TaskFinishParams
}

export class TaskEventTracker {
  private entries: Map<string, TaskEventCollector> = new Map()

  addTaskStart(params: TaskStartParams) {
    const newEntry: TaskEventCollector = {
      startParams: params,
      parents: [],
    }

    for (const parentId of params.taskId.parents ?? []) {
      const parent = this.entries.get(parentId)
      if (parent) {
        newEntry.parents.push(parent)
      }
    }

    this.entries.set(params.taskId.id, newEntry)
  }

  addTaskFinish(params: TaskFinishParams) {
    const entry = this.entries.get(params.taskId.id)
    if (entry) {
      entry.finishParams = params
    }
  }

  getTaskEvent(id: string): TaskEventCollector | undefined {
    return this.entries.get(id)
  }

  getBuildTargetId(id: string): BuildTargetIdentifier | undefined {
    let current = this.entries.get(id)
    while (current?.startParams.dataKind !== TaskStartDataKind.TestTask) {
      const firstParent = current?.parents[0]
      if (firstParent === undefined) return
      current = firstParent
    }

    if (current.startParams.dataKind === TaskStartDataKind.TestTask) {
      const testTask = current.startParams.data as TestTask
      return testTask.target
    }

    return undefined
  }
}

import * as vscode from 'vscode'
import {Inject, Injectable, OnModuleInit} from '@nestjs/common'
import {EXTENSION_CONTEXT_TOKEN} from '../custom-providers'
import {TestCaseStore} from './store'
import {LanguageToolManager, TestFileContents} from '../language-tools/manager'

/**
 * This will allow dummy run arrows to be applied to a document, to provide indication of out of scope files.
 * The resolver can use this class to enable or disable these decorators in a given file.
 */
@Injectable()
export class SyncHintDecorationsManager implements OnModuleInit {
  @Inject(EXTENSION_CONTEXT_TOKEN) private readonly ctx: vscode.ExtensionContext
  @Inject(TestCaseStore) private readonly store: TestCaseStore
  @Inject(LanguageToolManager)
  private readonly languageToolManager: LanguageToolManager

  private activeFiles = new Map<string, vscode.Disposable>()
  private hoverMessage: vscode.MarkdownString
  private decorationType: vscode.TextEditorDecorationType

  onModuleInit() {
    this.ctx.subscriptions.push(
      // Access to the Project View file for use in the markdown command on hover.
      vscode.commands.registerCommand('bazelbsp.openProjectView', async () => {
        const uri = this.store.testController.items.get('root')?.uri
        if (uri) {
          const document = await vscode.workspace.openTextDocument(uri)
          await vscode.window.showTextDocument(document)
        }
      })
    )

    // Set up the decorator type and hover message.
    this.decorationType = vscode.window.createTextEditorDecorationType({
      gutterIconPath: vscode.Uri.file(
        this.ctx.asAbsolutePath('resources/gutter.svg')
      ),
      isWholeLine: true,
      gutterIconSize: 'contain',
    })
    this.hoverMessage = new vscode.MarkdownString(
      '**Test Explorer**\n\nTests in this file are not yet synced.\n\n- [Adjust Project Scope](command:bazelbsp.openProjectView)\n\n- [Sync Now](command:testing.refreshTests)\n\n'
    )
    this.hoverMessage.isTrusted = true
  }

  /**
   * Enable decorators for a given file.
   * @param uri file on which to enable sync hint decorators.
   * @param repoRoot portion of the path representing this file's repo root.
   * @param docInfo existing processed test file contents for initial decorator positions.
   */
  async enable(uri: vscode.Uri, repoRoot: string, docInfo: TestFileContents) {
    const editor = vscode.window.visibleTextEditors.find(
      editor => editor.document.uri.toString() === uri.toString()
    )
    if (editor) this.setDecorationRanges(editor, docInfo)

    this.ensureWatcher(uri, repoRoot)
  }

  /**
   * Stop applying decorators for a given file, and clear if visible.
   * @param uri file on which decorators will be removed.
   */
  async disable(uri: vscode.Uri) {
    const watcher = this.activeFiles.get(uri.fsPath)
    if (watcher) {
      watcher.dispose()
      this.activeFiles.delete(uri.fsPath)

      const editor = vscode.window.visibleTextEditors.find(
        editor => editor.document.uri.toString() === uri.toString()
      )
      if (editor) this.setDecorationRanges(editor, null)
    }
  }

  /**
   * Determine current test case positions then apply the decorator.
   * @param editor text document to be updated.
   * @param repoRoot repo root to be used when getting
   */
  private async refreshDecoratorPositions(
    editor: vscode.TextEditor,
    repoRoot: string
  ) {
    const testFileContents = await this.languageToolManager
      .getLanguageToolsForFile(editor.document)
      .getDocumentTestCases(editor.document.uri, repoRoot)
    this.setDecorationRanges(editor, testFileContents)
  }

  /**
   * Adds a watcher for this file, reapplying the decorators each file the file is shown.
   * @param uri text document to be updated.
   * @param repoRoot portion of the path representing this file's repo root.
   */
  private ensureWatcher(uri: vscode.Uri, repoRoot: string) {
    const existing = this.activeFiles.get(uri.fsPath)
    if (existing) {
      existing.dispose()
    }

    const watcher = vscode.window.onDidChangeActiveTextEditor(async editor => {
      if (editor?.document.uri === uri) {
        await this.refreshDecoratorPositions(editor, repoRoot)
      }
    })

    this.activeFiles.set(uri.fsPath, watcher)
  }

  /**
   * Apply decorators to the given editor based on the provided TestFileContents.
   * @param editor editor to be updated.
   * @param docInfo processed test file information indication expected positions for documents. null to clear current contents.
   */
  private setDecorationRanges(
    editor: vscode.TextEditor,
    docInfo: TestFileContents | null
  ) {
    let ranges: vscode.Range[] = []
    if (docInfo) {
      ranges = docInfo.testCases.map(test => test.range)
    }

    const decorations: vscode.DecorationOptions[] = []
    for (const range of ranges) {
      decorations.push({
        range: new vscode.Range(range.start, range.start), // first line of the test only
        hoverMessage: this.hoverMessage,
      })
    }
    editor.setDecorations(this.decorationType, decorations)
  }
}

import * as vscode from 'vscode'
import {Inject} from '@nestjs/common'
import {TestItem} from 'vscode'
import path from 'path'

import {EXTENSION_CONTEXT_TOKEN} from '../custom-providers'
import {TestCaseStore} from '../test-explorer/store'
import {
  BuildTargetTestCaseInfo,
  SourceDirTestCaseInfo,
  SourceFileTestCaseInfo,
  TargetDirTestCaseInfo,
  TestCaseInfo,
  TestItemTestCaseInfo,
  TestItemType,
} from './test-info'
import {BuildTarget, SourceItem} from '../bsp/bsp'
import {DocumentTestItem, LanguageToolManager} from '../language-tools/manager'

/**
 * Class which includes various methods to create test items.
 * These each return a newly created test item, backed by a TestCaseInfo object added to the TestCaseStore.
 * The caller is responsible for adding the newly returned test item to the appropriate parent.
 */
export class TestItemFactory {
  @Inject(EXTENSION_CONTEXT_TOKEN) private readonly ctx: vscode.ExtensionContext
  @Inject(TestCaseStore) private readonly store: TestCaseStore
  @Inject(LanguageToolManager)
  private readonly languageToolManager: LanguageToolManager

  /**
   * Create a root test item for the test explorer.
   * @param uri URI of the test item.
   */
  createRootTestItem(uri?: vscode.Uri): TestItem {
    const newTest = this.store.testController.createTestItem(
      'root',
      'Bazel Test Targets',
      uri
    )
    newTest.range = new vscode.Range(0, 0, 0, 0)
    newTest.canResolveChildren = true
    this.store.testCaseMetadata.set(
      newTest,
      new TestCaseInfo(newTest, undefined, TestItemType.Root)
    )
    this.store.testController.items.replace([newTest])
    return newTest
  }

  /**
   * Creates a test item for a build target.
   * @param target BuildTarget corresponding to this test.
   * @param uri URI of the test item.
   * @returns The newly created test item.
   */
  createBuildTargetTestItem(target: BuildTarget, uri?: vscode.Uri): TestItem {
    const newTest = this.store.testController.createTestItem(
      target.id.uri,
      target.displayName ?? target.id.uri,
      uri
    )
    const testCaseInfo = new BuildTargetTestCaseInfo(
      newTest,
      target,
      this.languageToolManager.getLanguageTools(target)
    )
    this.store.testCaseMetadata.set(newTest, testCaseInfo)

    newTest.canResolveChildren = true
    testCaseInfo.setDisplayName()
    return newTest
  }

  /**
   * Creates a test item for a source file.
   * @param target BuildTarget corresponding to this test.
   * @param sourceItem SourceItem corresponding to this test.
   * @returns The newly created test item.
   */
  createSourceFileTestItem(
    target: BuildTarget,
    sourceItem: SourceItem
  ): TestItem {
    const id = `{sourcefile}:${target.id.uri}:${sourceItem.uri}`
    const label = target?.baseDirectory
      ? path.relative(target.baseDirectory, sourceItem.uri)
      : sourceItem.uri
    const newTest = this.store.testController.createTestItem(
      id,
      label,
      vscode.Uri.parse(sourceItem.uri)
    )
    this.store.testCaseMetadata.set(
      newTest,
      new SourceFileTestCaseInfo(
        newTest,
        target,
        this.languageToolManager.getLanguageTools(target)
      )
    )

    return newTest
  }

  /**
   * Creates test items representing segments of a path.
   * @param directories Mapping of directories to test items, specific to a given refresh.
   * @param dir Directory path (relative or absolute) which will be broken up into separate test items.
   * @param target (optional) Target that applies to these path segments.
   * @returns Root and base test items for the path segments.
   */
  createPathSegmentTestItems(
    directories: Map<string, vscode.TestItem>,
    dir: string,
    target?: BuildTarget
  ): {
    rootTestItem: vscode.TestItem
    baseTestItem: vscode.TestItem
  } {
    // Lowest child among the segments.
    let baseItem: undefined | vscode.TestItem
    // Prior visited item in the iteration.
    let priorItem: undefined | vscode.TestItem
    // Current item in the iteration.
    let currentItem: undefined | vscode.TestItem

    let currentPath = vscode.Uri.parse(dir).fsPath
    let shouldContinue = true
    do {
      // Get or create test item for this directory.
      currentItem = directories.get(currentPath)
      if (currentItem === undefined) {
        if (target) {
          // When a target is provided, create this as a source directory, so it is runnable on its own.
          currentItem = this.createSourceDirTestItem(
            target,
            currentPath,
            vscode.Uri.parse(currentPath)
          )
        } else {
          // When no target is provided, create it as a target directory, allowing targets beneath it to run.
          currentItem = this.createTargetDirTestItem(
            currentPath,
            vscode.Uri.parse(currentPath)
          )
        }
        directories.set(currentPath, currentItem)
      }

      if (priorItem) currentItem.children.add(priorItem)
      if (!baseItem) baseItem = currentItem

      // Move up the directory path
      priorItem = currentItem
      if (currentPath === path.dirname(currentPath)) {
        shouldContinue = false
      } else {
        currentPath = path.dirname(currentPath)
      }
    } while (shouldContinue)

    return {
      rootTestItem: currentItem,
      baseTestItem: baseItem,
    }
  }

  /**
   * Create a new item representing an individual test case within a source file.
   * @param details DocumentTestItem containing test case details to create the item.
   * @param target Target with which this test item should be associated.
   * @returns New TestItem with corresponding metadata representing an individual test case.
   */
  createTestCaseTestItem(
    details: DocumentTestItem,
    target: BuildTarget
  ): TestItem {
    const id = `{testcase}:${target.id.uri}:${details.uri.path}${
      details.parent ? `:${details.parent.name}` : ''
    }:${details.name}`
    const newTest = this.store.testController.createTestItem(
      id,
      details.name,
      details.uri
    )
    newTest.range = details.range
    this.store.testCaseMetadata.set(
      newTest,
      new TestItemTestCaseInfo(
        newTest,
        target,
        details,
        this.languageToolManager.getLanguageTools(target)
      )
    )
    return newTest
  }

  /**
   * Creates a test item for a build target's directory.
   * @param dir path to this directory.
   * @param uri URI of the test item.
   * @returns The newly created test item.
   */
  private createTargetDirTestItem(dir: string, uri: vscode.Uri): TestItem {
    const id = `{targetdir}:${uri.path}`
    const newTest = this.store.testController.createTestItem(id, dir, uri)
    this.store.testCaseMetadata.set(
      newTest,
      new TargetDirTestCaseInfo(newTest, dir)
    )
    return newTest
  }

  /**
   * Creates a test item for a source directory within a build target.
   * @param dir path to this directory
   * @param target BuildTarget corresponding to this test.
   * @param uri URI of the test item.
   * @returns The newly created test item.
   */
  private createSourceDirTestItem(
    target: BuildTarget,
    dir: string,
    uri: vscode.Uri
  ): TestItem {
    const id = `{sourcedir}:${target.id.uri}:${uri.path}`
    const relPath = path.relative(
      vscode.Uri.parse(target.baseDirectory ?? '').fsPath,
      dir
    )
    const newTest = this.store.testController.createTestItem(id, relPath, uri)
    this.store.testCaseMetadata.set(
      newTest,
      new SourceDirTestCaseInfo(
        newTest,
        target,
        relPath,
        this.languageToolManager.getLanguageTools(target)
      )
    )
    return newTest
  }
}

import * as vscode from 'vscode'
import * as path from 'path'
import {BuildTarget, TestParams, TestResult, StatusCode} from '../bsp/bsp'
import {TestParamsDataKind, BazelTestParamsData} from '../bsp/bsp-ext'
import {TestCaseStatus, TestRunTracker} from '../test-runner/run-tracker'
import type {DocumentTestItem, LanguageTools} from '../language-tools/manager'

export enum TestItemType {
  Root,
  BazelTarget,
  TargetDirectory,
  SourceDirectory,
  SourceFile,
  TestSuite,
  TestCase,
}

/**
 * Base class for test case information, to be extended by specific test case types.
 * The base class can be used to provide generic test items that defer the actual BSP execution to their children.
 * Use one of the extended classes for test cases that can be run directly.
 */
export class TestCaseInfo {
  public readonly type: TestItemType
  public readonly target: BuildTarget | undefined
  public readonly testItem: vscode.TestItem

  constructor(
    test: vscode.TestItem,
    target?: BuildTarget,
    type: TestItemType = TestItemType.Root
  ) {
    this.testItem = test
    this.type = type
    this.target = target
  }

  /**
   * Prepare the test run parameters for this test case.
   * @param currentRun TestRunTracker for the current test run.
   * @returns TestParams to use in the Bazel BSP request, or undefined if the test case is not independently runnable.
   */
  prepareTestRunParams(currentRun: TestRunTracker): TestParams | undefined {
    return
  }

  /**
   * Process the test result and update the current run based on test outcome.
   * @param currentRun TestRunTracker for the current test run.
   * @param result TestResult returned by this run's request to the build server.
   */
  processTestRunResult(currentRun: TestRunTracker, result: TestResult): void {
    throw Error(
      'called processTestRunResult on a test case that cannot be directly run'
    )
  }

  /**
   * Refreshes the name displayed for the test item.
   * Base implementation leaves the label unchanged.
   * @param relativeToItem (optional) Item against which a relative path will be calculated, for subclasses that support it.
   */
  setDisplayName(relativeToItem?: TestCaseInfo | undefined) {}
}

/**
 * Test case information to represent a directory containing sources within a target.
 */
export class TargetDirTestCaseInfo extends TestCaseInfo {
  private readonly dir: string
  constructor(test: vscode.TestItem, dir: string) {
    super(test, undefined, TestItemType.TargetDirectory)
    this.dir = dir
  }

  /**
   * Calculate relative path to another target directory and set it as display name.
   * @param relativeToItem Item based on which the relative path will be calculated.
   */
  setDisplayName(relativeToItem?: TestCaseInfo | undefined) {
    if (relativeToItem?.type === TestItemType.TargetDirectory) {
      // If the relative item is another TargetDirTestCaseInfo, calculate relative path.
      this.testItem.label = path.relative(
        (relativeToItem as TargetDirTestCaseInfo).dir,
        this.dir
      )
    } else {
      // If it is another type of test item, use the full path.
      this.testItem.label = this.dir
    }
  }
}

/**
 * Test case information for a full BSP build target.  Includes logic to prepare and process test runs.
 * Currently, BSP can execute full targets, so this serves as the main unit of execution.
 */
export class BuildTargetTestCaseInfo extends TestCaseInfo {
  public readonly type: TestItemType
  public readonly target: BuildTarget
  protected readonly languageTools: LanguageTools | undefined

  constructor(
    test: vscode.TestItem,
    target: BuildTarget,
    languageTools?: LanguageTools
  ) {
    super(test, target)
    this.type = TestItemType.BazelTarget
    // This class and any that extend it are guaranteed to include a target.
    this.target = target
    this.languageTools = languageTools
  }

  prepareTestRunParams(currentRun: TestRunTracker): TestParams | undefined {
    if (this.target === undefined) return

    const bazelParams: BazelTestParamsData = {
      coverage:
        currentRun.getRunProfileKind() === vscode.TestRunProfileKind.Coverage,
    }

    // Includes additional debug-specific flags when necessary.
    if (currentRun.getRunProfileKind() === vscode.TestRunProfileKind.Debug) {
      const configuredFlags = currentRun.getDebugBazelFlags()
      if (configuredFlags && configuredFlags.length > 0) {
        // Bazel BSP accepts whitespace separated list of flags.
        bazelParams.additionalBazelParams = configuredFlags.join(' ')
      }
    }

    // Additional Bazel params is not supported in BSP coverage for now
    const ideTag = currentRun.getIdeTag()
    if (ideTag && !bazelParams.coverage) {
      if (bazelParams.additionalBazelParams) {
        bazelParams.additionalBazelParams += ` ${ideTag}`
      } else {
        bazelParams.additionalBazelParams = ideTag
      }
    }

    const params = {
      targets: [this.target.id],
      originId: currentRun.originName,
      arguments: [],
      environmentVariables: {},
      workingDirectory: '',
      dataKind: TestParamsDataKind.BazelTest,
      data: bazelParams,
    }

    return params
  }

  /**
   * Update the test item's status based on the result of the test run.
   * This implementation updates the status of the target itself, and then updates all pending children that are not targets of their own.
   * @param currentRun TestRunTracker for the current test run.
   * @param result TestResult returned by this run's request to the build server.
   */
  processTestRunResult(currentRun: TestRunTracker, result: TestResult): void {
    // The executed test item inherits the overall run status.
    updateStatus(this.testItem, currentRun, result)

    // Update remaining children that are more specific than this item's type.
    // Other targets are left in a pending state so they can run on their own.
    for (const child of currentRun.pendingChildrenIterator(
      this.testItem,
      TestItemType.BazelTarget
    )) {
      if (result.statusCode === StatusCode.Error) {
        // On error, mark children that didn't receive individual results as failed.
        currentRun.updateStatus(child.testItem, TestCaseStatus.Failed)
      } else {
        // On success, let Test Explorer determine status based on children's outcomes.
        currentRun.updateStatus(child.testItem, TestCaseStatus.Inherit)
      }
    }
  }

  /**
   * Sets the display name to the target's label.
   * @param relativeToItem will be ignored in this implementation
   */
  setDisplayName(relativeToItem?: TestCaseInfo | undefined) {
    if (this.target.languageIds?.includes('typescript')) {
      this.testItem.label = this.target.displayName ?? this.target.id.uri
    } else {
      this.testItem.label =
        this.target.id.uri.split(':').pop() ?? this.target.id.uri
      this.testItem.description = this.target.displayName
    }
  }
}

/**
 * Test case information for a source directory within a build target.
 */
export class SourceDirTestCaseInfo extends BuildTargetTestCaseInfo {
  public readonly type: TestItemType
  private readonly dir: string
  constructor(
    test: vscode.TestItem,
    target: BuildTarget,
    dir: string,
    languageTools?: LanguageTools
  ) {
    super(test, target, languageTools)
    this.dir = dir
    this.type = TestItemType.SourceDirectory
  }

  prepareTestRunParams(currentRun: TestRunTracker): TestParams | undefined {
    if (this.languageTools?.shouldDeferSourceDirectoryRun()) {
      return
    }

    return super.prepareTestRunParams(currentRun)
  }

  /**
   * Sets a source directory's name to be relative to any parent source directory.
   * @param relativeToItem Item against which the label will be calculated.
   */
  setDisplayName(relativeToItem?: TestCaseInfo | undefined) {
    if (relativeToItem?.type === TestItemType.SourceDirectory) {
      this.testItem.label = path.relative(
        (relativeToItem as SourceDirTestCaseInfo).dir,
        this.dir
      )
    } else {
      this.testItem.label = this.dir
    }
  }
}

/**
 * Test case information for a source file within a target.
 * Current behavior is identical to BuildTargetTestCaseInfo, but in the future this can add filtering by file.
 */
export class SourceFileTestCaseInfo extends BuildTargetTestCaseInfo {
  public readonly type: TestItemType
  protected details: DocumentTestItem | undefined

  constructor(
    test: vscode.TestItem,
    target: BuildTarget,
    languageTools?: LanguageTools
  ) {
    super(test, target, languageTools)
    this.type = TestItemType.SourceFile
  }

  prepareTestRunParams(currentRun: TestRunTracker): TestParams | undefined {
    if (this.target === undefined) return

    const params = super.prepareTestRunParams(currentRun)

    const fileArgument = this.getTestFileArgument()
    if (fileArgument) {
      params?.arguments?.push(fileArgument)
    }

    if (
      params?.dataKind === TestParamsDataKind.BazelTest &&
      this.type === TestItemType.TestCase &&
      this.details?.testFilter
    ) {
      const bazelParams = params.data as BazelTestParamsData
      bazelParams.testFilter = this.details.testFilter
    }

    return params
  }

  processTestRunResult(currentRun: TestRunTracker, result: TestResult): void {
    updateStatus(this.testItem, currentRun, result)

    for (const child of currentRun.pendingChildrenIterator(
      this.testItem,
      TestItemType.SourceFile
    )) {
      if (result.statusCode === StatusCode.Ok) {
        currentRun.updateStatus(child.testItem, TestCaseStatus.Passed)
      } else if (child.testItem.children.size > 0) {
        currentRun.updateStatus(child.testItem, TestCaseStatus.Inherit)
      }
    }
  }

  private getTestFileArgument(): string | undefined {
    const uri = this.details?.uri ?? this.testItem.uri
    return this.languageTools?.getTestFileArgument(uri)
  }

  /**
   * Sets a source file's label to its file name.
   * @param relativeToItem will be ignored in this implementation
   */
  setDisplayName(relativeToItem?: TestCaseInfo | undefined) {
    if (this.details) {
      this.testItem.label = this.details.name
    } else {
      this.testItem.label = path.basename(this.testItem.uri?.path ?? '')
    }
  }

  /**
   * Update the document's test item details.
   * @param details DocumentTestItem representing a test item for the full document.
   */
  setDocumentTestItem(details: DocumentTestItem) {
    this.details = details
    this.testItem.range = details.range
    this.setDisplayName()
  }

  getDocumentTestItem(): DocumentTestItem | undefined {
    return this.details
  }
}

/**
 * Test case information for a single test case within a file.
 * Includes the applicable test filter to run only this test case.
 */
export class TestItemTestCaseInfo extends SourceFileTestCaseInfo {
  public readonly type: TestItemType
  protected details: DocumentTestItem

  constructor(
    test: vscode.TestItem,
    target: BuildTarget,
    details: DocumentTestItem,
    languageTools?: LanguageTools
  ) {
    super(test, target, languageTools)
    this.type = TestItemType.TestCase
    this.details = details
  }

  processTestRunResult(currentRun: TestRunTracker, result: TestResult): void {
    if (
      result.statusCode === StatusCode.Error &&
      this.testItem.children.size > 0
    ) {
      currentRun.updateStatus(this.testItem, TestCaseStatus.Inherit)

      for (const child of currentRun.pendingChildrenIterator(
        this.testItem,
        TestItemType.SourceFile
      )) {
        if (child.testItem.children.size > 0) {
          currentRun.updateStatus(child.testItem, TestCaseStatus.Inherit)
        }
      }

      return
    }

    super.processTestRunResult(currentRun, result)
  }

  /**
   * Sets a test case's label to its name.
   * @param relativeToItem will be ignored in this implementation
   */
  setDisplayName(relativeToItem?: TestCaseInfo | undefined) {
    this.testItem.label = this.details.name
  }
}

function updateStatus(
  item: vscode.TestItem,
  currentRun: TestRunTracker,
  result: TestResult
) {
  if (result.statusCode === StatusCode.Error) {
    const stdOut = result.data?.stdoutCollector?.lines
    const testMessage = stdOut
      ? new vscode.TestMessage(stdOut.join('\n'))
      : undefined
    currentRun.updateStatus(item, TestCaseStatus.Failed, testMessage)
  } else if (result.statusCode === StatusCode.Ok) {
    currentRun.updateStatus(item, TestCaseStatus.Passed)
  } else {
    currentRun.updateStatus(item, TestCaseStatus.Skipped)
  }
}

import * as vscode from 'vscode'

import {TestCaseInfo, TestItemType} from '../test-info/test-info'
import {
  BuildTarget,
  LogMessageParams,
  TaskFinishDataKind,
  TaskFinishParams,
  TaskStartParams,
  TestFinish,
  TestStatus,
} from '../bsp/bsp'
import {TaskOriginHandlers} from '../test-explorer/client'
import {
  JUnitStyleTestCaseData,
  PublishOutputDataKind,
  PublishOutputParams,
  TestCoverageReport,
  TestFinishDataKind,
} from '../bsp/bsp-ext'
import {CoverageTracker} from '../coverage-utils/coverage-tracker'
import {LanguageToolManager} from '../language-tools/manager'
import {TaskEventTracker} from './task-events'
import {ANSI_CODES, Utils} from '../utils/utils'
import {getExtensionSetting, SettingName} from '../utils/settings'

export enum TestCaseStatus {
  Pending,
  Started,
  Passed,
  Failed,
  Skipped,
  Errored,
  // Defer to Test Explorer's automatic status determination based on outcome of an item's children.
  Inherit,
}

export interface RunTrackerParams {
  testCaseMetadata: WeakMap<vscode.TestItem, TestCaseInfo>
  run: vscode.TestRun
  request: vscode.TestRunRequest
  originName: string
  cancelToken: [REDACTED]
  coverageTracker: CoverageTracker
  languageToolManager: LanguageToolManager
}

type DebugInfo = {
  debugFlags?: string[]
  launchConfig?: vscode.DebugConfiguration
  readyPattern?: RegExp
  remoteRoot?: string
  localRoot?: string
}

export class TestRunTracker implements TaskOriginHandlers {
  // All tests that are included in this run. See iterator definition below.
  private allTests: Map<TestItemType, TestCaseInfo[]>
  private testsByLookupKey: Map<string, TestCaseInfo>
  private buildTargets: Map<string, BuildTarget>

  // Current status of each TestItem in the run, initially Pending for all TestItems.
  private status: Map<vscode.TestItem, TestCaseStatus>

  private request: vscode.TestRunRequest
  private testCaseMetadata: WeakMap<vscode.TestItem, TestCaseInfo>
  private run: vscode.TestRun
  private _originName: string
  private onDoneCallback: () => void
  private cancelToken: [REDACTED]
  private coverageTracker: CoverageTracker
  private languageToolManager: LanguageToolManager
  private pending: Thenable<void>[] = []
  private buildTaskTracker: TaskEventTracker = new TaskEventTracker()
  private debugInfo: DebugInfo | undefined
  private hasDebugSessionBeenInitiated = false
  private lastAttachedEndpoint: string | undefined
  private ideTag: string
  constructor(params: RunTrackerParams) {
    this.allTests = new Map<TestItemType, TestCaseInfo[]>()
    this.status = new Map<vscode.TestItem, TestCaseStatus>()
    this.testCaseMetadata = params.testCaseMetadata
    this.run = params.run
    this.request = params.request
    this._originName = params.originName
    this.cancelToken = [REDACTED]
    this.coverageTracker = params.coverageTracker
    this.languageToolManager = params.languageToolManager
    this.ideTag = 'unknown'

    this.prepareCurrentRun()
    this.prepareDebugInfo()
  }

  public get originName(): string {
    return this._originName
  }

  /**
   * Iterates through each item in the test run request, and its children.
   * Ordered by TestItemType, working its way down in rank until all items have been run. Includes only pending items.
   * During a run, it is expected that the callback will call updateStatus at least once to report test outcome.
   * The callback may optionally update a test's children as well.
   * If an item is no longer pending by the time it is reached in the iteration, it will be skipped.
   * If the run is canceled, the remaining items will be skipped.
   * @param callback Callback containing the test execution logic for a given test case.
   */
  public async executeRun(
    callback: (
      item: vscode.TestItem,
      cancelToken: [REDACTED]
    ) => Promise<void>
  ) {
    // All items below the roots of the TestRunRequest will be shown as enqueued.
    for (const item of this) {
      this.run.enqueued(item.testItem)
    }

    // Run the callback for each test case.
    for (const item of this) {
      if (this.cancelToken.isCancellationRequested) {
        this.run.appendOutput(
          'Run canceled by user.  Remaining items will be skipped.\r\n'
        )
        break
      }

      const initialStatus = TestCaseStatus.Started
      this.updateStatus(item.testItem, initialStatus)
      await callback(item.testItem, this.cancelToken)

      if (this.status.get(item.testItem) === initialStatus) {
        // Container nodes that defer execution to their children should not
        // override the aggregate child status in Test Explorer.
        const fallbackStatus =
          item.testItem.children.size > 0
            ? TestCaseStatus.Inherit
            : TestCaseStatus.Skipped
        this.updateStatus(item.testItem, fallbackStatus)
      }
    }

    await Promise.all(this.pending)
    this.run.end()
    if (this.onDoneCallback) this.onDoneCallback()
  }

  /**
   * Updates an item's status, both within this test run tracker and in the test explorer UI.
   * This may be called more than once for the same test item, in which case only the highest status (per TestCaseStatus enum) will be retained.
   * @param item TestItem for which the status will be updated.
   * @param status New status value.
   * @param message (optional) Message to be shown to report an outcome. Only applicable for Failed and Errored states.
   */
  public updateStatus(
    item: vscode.TestItem,
    status: TestCaseStatus,
    message?: vscode.TestMessage
  ) {
    const currentStatus = this.status.get(item)
    if (currentStatus && status < currentStatus) {
      // Only update if the new status is ranked higher than the existing one.
      // This allows multiple updates to be made to a test item, while only showing the highest status in the UI.
      return
    }

    this.status.set(item, status)
    switch (status) {
      case TestCaseStatus.Started:
        this.run.started(item)
        break
      case TestCaseStatus.Failed:
        this.run.failed(item, message ?? new vscode.TestMessage(''))
        break
      case TestCaseStatus.Errored:
        this.run.errored(item, message ?? new vscode.TestMessage(''))
        break
      case TestCaseStatus.Passed:
        this.run.passed(item)
        break
      case TestCaseStatus.Inherit:
        break
      case TestCaseStatus.Skipped:
      default:
        this.run.skipped(item)
        break
    }
  }

  public onBuildTaskStart(params: TaskStartParams) {
    this.buildTaskTracker.addTaskStart(params)
  }

  public onBuildTaskFinish(params: TaskFinishParams) {
    this.buildTaskTracker.addTaskFinish(params)

    if (params.dataKind !== TaskFinishDataKind.TestFinish) {
      return
    }

    const testFinishData = params.data as TestFinish
    if (testFinishData.dataKind === TestFinishDataKind.JUnitStyleTestCaseData) {
      // Workaround for missing target ID and parent task bug in bazel-bsp server (https://youtrack.jetbrains.com/issue/BAZEL-1585).
      // For now, test runs that contain the same test case in multiple targets of the run will all use the same result.
      let hasMatch = false
      for (const target of this.buildTargets.values()) {
        const key = this.languageToolManager
          .getLanguageTools(target)
          .mapTestFinishDataToLookupKey(testFinishData)

        if (!key) {
          continue
        }

        // Find the matching item and post the updated status.
        const item = this.testsByLookupKey.get(key)
        if (item) {
          this.updateStatusFromTestFinishData(item, testFinishData)
          hasMatch = true
        }
      }

      if (!hasMatch) {
        this.run.appendOutput('\n\r')
        this.run.appendOutput(
          `Updating ${testFinishData.displayName}: Unable to match this test result to an item in this run.`
        )
      }
    }
  }

  /**
   * Appends a log message to this tracker's test run output.
   * @param params Log message to be appended.
   */
  public onBuildLogMessage(params: LogMessageParams) {
    if (params.message.endsWith('\\')) {
      // Combine messages that are continued on the following line.
      this.run.appendOutput(params.message.slice(0, -1))
    } else {
      this.run.appendOutput(params.message)
      this.run.appendOutput('\n\r')
    }

    if (
      this.debugInfo?.launchConfig &&
      this.debugInfo.readyPattern?.test(params.message)
    ) {
      const match = params.message.match(/ws:\/\/([^:]+):(\d+)\//)
      if (match) {
        this.attachDebugger({host: match[1], port: parseInt(match[2], 10)})
      } else {
        this.startConfiguredDebugSession()
      }
    }
  }

  /**
   * In multi-process environments (e.g. Jazelle/Bazel), wrapper processes
   * emit debug endpoints before the real test runner. With --inspect-brk,
   * each process pauses at startup. When a new endpoint appears, we
   * resume the current wrapper and re-attach to the new one. The last
   * endpoint is the real test process where breakpoints will be hit.
   */
  private async attachDebugger(endpoint: {
    host: string
    port: number
  }): Promise<void> {
    if (!this.debugInfo?.launchConfig) return

    const endpointKey = `${endpoint.host}:${endpoint.port}`
    if (this.lastAttachedEndpoint === endpointKey) return
    this.lastAttachedEndpoint = endpointKey

    this.run.appendOutput(
      `Debug endpoint detected: ${endpoint.host}:${endpoint.port}\r\n`
    )

    const session = vscode.debug.activeDebugSession
    if (session) {
      try {
        await session.customRequest('continue', {threadId: 1})
      } catch {
        this.run.appendOutput(
          'Unable to resume active debug session for reattach. Keeping current session.\r\n'
        )
        this.lastAttachedEndpoint = undefined
        return
      }
      await vscode.debug.stopDebugging(session)
    }

    this.run.appendOutput(
      `Attaching debugger to ${endpoint.host}:${endpoint.port} [Launch config: '${this.debugInfo.launchConfig.name}']\r\n`
    )

    const debugConfig = {...this.debugInfo.launchConfig}
    debugConfig.port = endpoint.port
    debugConfig.address = endpoint.host
    if (this.debugInfo.localRoot && this.debugInfo.remoteRoot) {
      debugConfig.localRoot = this.debugInfo.localRoot
      debugConfig.remoteRoot = this.debugInfo.remoteRoot
      this.run.appendOutput(
        `Debug paths:\r\n  localRoot: ${debugConfig.localRoot}\r\n  remoteRoot: ${debugConfig.remoteRoot}\r\n`
      )
    }

    await vscode.debug.startDebugging(
      vscode.workspace.workspaceFolders?.[0],
      debugConfig
    )
  }

  /**
   * Fallback for non-Node debug flows (Java, Python, etc.) where the ready
   * pattern matches but the log message doesn't contain a ws:// endpoint.
   * Launches the configured debug profile once using its existing settings.
   */
  private startConfiguredDebugSession(): void {
    if (!this.debugInfo?.launchConfig || this.hasDebugSessionBeenInitiated) {
      return
    }
    this.hasDebugSessionBeenInitiated = true

    this.run.appendOutput(
      `Starting remote debug session [Launch config: '${this.debugInfo.launchConfig.name}']\r\n`
    )

    const debugConfig = {...this.debugInfo.launchConfig}
    if (this.debugInfo.localRoot && this.debugInfo.remoteRoot) {
      debugConfig.localRoot = this.debugInfo.localRoot
      debugConfig.remoteRoot = this.debugInfo.remoteRoot
      this.run.appendOutput(
        `Debug paths:\r\n  localRoot: ${debugConfig.localRoot}\r\n  remoteRoot: ${debugConfig.remoteRoot}\r\n`
      )
    }

    vscode.debug.startDebugging(
      vscode.workspace.workspaceFolders?.[0],
      debugConfig
    )
  }

  /**
   * Collects selected info that may be reported via progress events.
   * @param params Progress event containing data to be collected.
   */
  public onBuildPublishOutput(params: PublishOutputParams): void {
    if (params.dataKind === PublishOutputDataKind.CoverageReport) {
      const data = params.data as TestCoverageReport
      this.pending.push(
        this.coverageTracker.handleCoverageReport(this.run, data.lcovReportUri)
      )
    }
  }

  /**
   * Registers a callback that will be called after the last test item in the run has been processed.
   */
  public async onDone(callback: () => void) {
    this.onDoneCallback = callback
  }

  public getRunProfileKind(): vscode.TestRunProfileKind | undefined {
    return this.request.profile?.kind
  }

  public getDebugBazelFlags(): string[] | undefined {
    return this.debugInfo?.debugFlags
  }

  /**
   * Collects and stores the parents and all children to be included in this test run.
   * Populates maps to group the test items by their TestItemType and current status.
   */
  private prepareCurrentRun() {
    if (this.request.include === undefined) {
      return
    }

    for (const testItem of this.request.include) {
      this.recursivelyCollectChildren(
        this.allTests,
        testItem,
        undefined,
        TestCaseStatus.Pending
      )
    }

    // Make items readily available for lookup.
    this.testsByLookupKey = new Map<string, TestCaseInfo>()
    this.buildTargets = new Map<string, BuildTarget>()
    for (const item of this) {
      const lookupKey = this.languageToolManager
        .getLanguageTools(item.target)
        .mapTestCaseInfoToLookupKey(item)
      if (lookupKey) this.testsByLookupKey.set(lookupKey, item)
      if (item.target) this.buildTargets.set(item.target.id.uri, item.target)
    }
  }

  /**
   * During debug runs, this collects and stores the necessary settings that will be applied through this run.
   * In the event that a setting is not found, information will be printed with the test output, but the run will still attempt to proceed.
   */
  private prepareDebugInfo() {
    if (this.getRunProfileKind() !== vscode.TestRunProfileKind.Debug) {
      return
    }

    // Determine configured launch configuration name.
    const configName = getExtensionSetting(SettingName.LAUNCH_CONFIG_NAME)
    if (!configName) {
      this.run.appendOutput(
        'No launch configuration name is configured. Debugger will not connect automatically for this run.\r\n'
      )
      this.run.appendOutput(
        'Check the `bazelbsp.debug.profileName` VS Code setting to ensure it corresponds to a valid launch configuration.\r\n'
      )
      return
    }

    // Store the selected launch configuration.
    const launchConfigurations = vscode.workspace.getConfiguration('launch')
    const configurations =
      launchConfigurations.get<any[]>('configurations') || []
    const selectedConfig = configurations.find(
      config => config.name !== undefined && config.name === configName
    )
    if (!selectedConfig) {
      this.run.appendOutput(
        `Unable to find debug profile ${configName}. Debugger will not connect automatically for this run.\r\n`
      )
      this.run.appendOutput(
        'Check the `bazelbsp.debug.profileName` VS Code setting to ensure it corresponds to a valid launch configuration.\r\n'
      )
    }

    // Ensure that matcher pattern is set for the output.
    const readyPattern = getExtensionSetting(SettingName.DEBUG_READY_PATTERN)
    if (!readyPattern) {
      this.run.appendOutput(
        'No matcher pattern is set. Debugger will not connect automatically for this run.\r\n'
      )
      this.run.appendOutput(
        'Check the `bazelbsp.debug.readyPattern` VS Code setting to ensure that a pattern is set.\r\n'
      )
    }

    // Ensure that matcher pattern is set for the output.
    let debugFlags = getExtensionSetting(SettingName.DEBUG_BAZEL_FLAGS)
    if (!debugFlags) {
      this.run.appendOutput(
        'No additional debug-specific Bazel flags have been found for this run.\r\n'
      )
      this.run.appendOutput(
        'Check the `bazelbsp.debug.bazelFlags` VS Code setting to ensure that necessary flags are set.\r\n'
      )
    }

    const workspaceRoot = vscode.workspace.workspaceFolders?.[0]?.uri.fsPath
    let remoteRoot: string | undefined
    let targetUri: string | undefined
    let target: BuildTarget | undefined

    for (const testCaseInfo of this) {
      if (testCaseInfo.target) {
        target = testCaseInfo.target
        targetUri = testCaseInfo.target.id.uri
        break
      }
    }

    if (workspaceRoot && targetUri && target) {
      remoteRoot = this.languageToolManager
        .getLanguageTools(target)
        .getDebugRemoteRoot(workspaceRoot, targetUri)
    }

    this.debugInfo = {
      debugFlags: debugFlags,
      launchConfig: selectedConfig,
      readyPattern: readyPattern ? new RegExp(readyPattern) : undefined,
      localRoot: workspaceRoot,
      remoteRoot: remoteRoot,
    }
  }

  /**
   * Iterate recursively through all children of the given test item, and collect them in the destination map.
   * @param destination Map to be populated with the collected test items, grouped by TestItemType.
   * @param item root item at which to begin traversal. The root item will also be included in the map.
   * @param filterLevel (optional) TestItemType which will be used as the cutoff for filtering. Items at or above this level will be excluded.
   * @param newStatus (optional) Status to be set for each item as it is collected.
   */
  private recursivelyCollectChildren(
    destination: Map<TestItemType, TestCaseInfo[]>,
    item: vscode.TestItem,
    filterLevel?: TestItemType,
    newStatus?: TestCaseStatus
  ) {
    const collectChildren = (currentItem: vscode.TestItem) => {
      const data = this.testCaseMetadata.get(currentItem)
      if (newStatus !== undefined) this.status.set(currentItem, newStatus)

      if (!data) return
      if (filterLevel !== undefined && data.type <= filterLevel) return

      // Add each test item to the appropriate map entry based on its TestItemType.
      const existingEntry = destination.get(data.type)
      if (!existingEntry) {
        destination.set(data.type, [data])
      } else {
        existingEntry.push(data)
      }

      // Recursively collect children.
      currentItem.children.forEach(child => collectChildren(child))
    }
    collectChildren(item)
  }

  /**
   * Iterates through each pending test case, ordered by TestItemType.
   * This defines the ordering in which nodes will be traversed and executed during a run.
   * */
  *[Symbol.iterator]() {
    const items = this.pendingTestItemIterator(this.allTests)
    for (const item of items) {
      yield item
    }
  }

  /**
   * Iterates through all pending test cases below the given test item, ordered by TestItemType.
   * This can be used for updates to the tree below a certain parent.
   * @param parent Parent test item whose children will be included in the iteration sequence.
   * @param filterLevel (optional) TestItemType which will be used as the cutoff for filtering. Items at or above this level will be excluded.
   * @returns Iterable sequence of pending children below the given parent.
   */
  *pendingChildrenIterator(
    parent: vscode.TestItem,
    filterLevel?: TestItemType
  ) {
    // Recursively collect all children of this test case into a map grouped by TestItemType.
    const currentChildren = new Map<TestItemType, TestCaseInfo[]>()
    parent.children.forEach(child => {
      this.recursivelyCollectChildren(currentChildren, child, filterLevel)
    })

    // Use the existing pendingItems iteration sequence to pass through only the relevant children.
    const items = this.pendingTestItemIterator(currentChildren)
    for (const item of items) {
      yield item
    }
  }

  /**
   * Iterates through all pending test cases, ordered by TestItemType.
   * The pending status will be checked immediately prior to yielding.
   * @param allItems All test items to be visited in this iteration sequence, organized their TestItemType.
   */
  private *pendingTestItemIterator(
    allItems: Map<TestItemType, TestCaseInfo[]>
  ) {
    for (const key of Object.keys(TestItemType)) {
      const testItemType = TestItemType[key]
      const testItems = allItems.get(testItemType)
      if (testItems) {
        for (const item of testItems) {
          if (this.status.get(item.testItem) === TestCaseStatus.Pending) {
            yield item
          }
        }
      }
    }
  }

  private updateStatusFromTestFinishData(
    item: TestCaseInfo,
    testFinishData: TestFinish
  ) {
    switch (testFinishData.status) {
      case TestStatus.Skipped:
      case TestStatus.Ignored:
        this.updateStatus(item.testItem, TestCaseStatus.Skipped)
        break
      case TestStatus.Passed:
        this.updateStatus(item.testItem, TestCaseStatus.Passed)
        break
      case TestStatus.Cancelled:
        this.updateStatus(
          item.testItem,
          TestCaseStatus.Errored,
          new vscode.TestMessage('Cancelled')
        )
        break
      case TestStatus.Failed:
        this.updateStatus(
          item.testItem,
          TestCaseStatus.Failed,
          formatTestResultMessage(testFinishData)
        )
    }
  }

  /**
   * Set the IDE tag to be used for this test run
   * @param ideClient IDE client identifier (e.g., 'vscode', 'cursor')
   */
  public setIdeTag(ideClient: string): void {
    // use test_env to set the IDE_CLIENT environment variable
    this.ideTag = `--test_env=IDE_CLIENT=${ideClient}`
  }

  /**
   * Get the IDE tag for this test run
   * @returns The IDE client identifier
   */
  public getIdeTag(): string {
    return this.ideTag
  }
}

function formatTestResultMessage(
  result: TestFinish
): vscode.TestMessage | undefined {
  let message =
    // Ignore 'null' string as well.
    // TODO(IDE-1133): Ensure server does not convert null values to string.
    result.message !== undefined && result.message !== 'null'
      ? `${ANSI_CODES.CYAN}${ANSI_CODES.BOLD}${result.message}${ANSI_CODES.RESET}\n\n`
      : ''

  if (result.dataKind === TestFinishDataKind.JUnitStyleTestCaseData) {
    const testCaseData = result.data as JUnitStyleTestCaseData
    if (result.displayName) {
      message += `${ANSI_CODES.RED}[TEST CASE]${ANSI_CODES.RESET} ${result.displayName}\n\n`
    }
    if (testCaseData.errorType && testCaseData.errorType !== 'null') {
      message += `${ANSI_CODES.RED}[ERROR TYPE]${ANSI_CODES.RESET} ${testCaseData.errorType}\n\n`
    }
    if (testCaseData.errorMessage && testCaseData.errorMessage !== 'null') {
      message += `${ANSI_CODES.RED}[ERROR]${ANSI_CODES.RESET} ${testCaseData.errorMessage}\n\n`
    }
    if (testCaseData.errorContent && testCaseData.errorContent !== 'null') {
      message += `${ANSI_CODES.RED}[FULL ERROR]${ANSI_CODES.RESET}\n\n${testCaseData.errorContent}\n\n`
    }
  }

  return new vscode.TestMessage(message)
}

import * as vscode from 'vscode'
import * as bsp from '../bsp/bsp'
import {Inject, OnModuleInit} from '@nestjs/common'

import {
  EXTENSION_CONTEXT_TOKEN,
  TEST_CONTROLLER_TOKEN,
} from '../custom-providers'
import {TestCaseInfo} from '../test-info/test-info'
import {BuildTargetIdentifier} from 'src/bsp/bsp'

const CONTEXT_KEY_TARGETS_RESULT = 'testExplorerBuildTargetsResult'
const CONTEXT_KEY_SOURCES_RESULT = 'testExplorerSourcesResult'

export class TestCaseStore implements OnModuleInit, vscode.Disposable {
  @Inject(EXTENSION_CONTEXT_TOKEN) private readonly ctx: vscode.ExtensionContext
  @Inject(TEST_CONTROLLER_TOKEN) readonly testController: vscode.TestController

  testCaseMetadata: WeakMap<vscode.TestItem, TestCaseInfo>

  // Watcher to update a test item's children.  Key corresponds to the test item ID.
  testItemWatchers: Map<string, vscode.FileSystemWatcher>
  knownFiles: Set<string>
  targetIdentifiers: Map<string, vscode.TestItem>

  constructor() {
    this.testCaseMetadata = new WeakMap<vscode.TestItem, TestCaseInfo>()
    this.testItemWatchers = new Map()
    this.targetIdentifiers = new Map<string, vscode.TestItem>()
    this.knownFiles = new Set<string>()
  }

  onModuleInit() {
    this.ctx.subscriptions.push(this)
  }

  dispose() {
    this.testController.dispose()
    for (const watcher of this.testItemWatchers.values()) {
      watcher.dispose()
    }
  }

  /**
   * Stores a single watcher for the given TestItem.id value, disposing of any existing watcher if present.
   * @param id TestItem ID for which to store the watcher.
   * @param watcher FileSystemWatcher which has already been created, or undefined to clear the watcher.
   */
  updateTestItemWatcher(id: string, watcher?: vscode.FileSystemWatcher) {
    const oldWatcher = this.testItemWatchers.get(id)
    if (oldWatcher) {
      oldWatcher.dispose()
    }
    if (watcher) this.testItemWatchers.set(id, watcher)
    else this.testItemWatchers.delete(id)
  }

  /**
   * Clear all existing watchers for the given TestItem and its children.
   * @param parentTest Parent test below which all watchers will be cleared, inclusive of the parent.
   */
  clearTestItemWatchers(parentTest: vscode.TestItem) {
    const clear = (test: vscode.TestItem) => {
      test.children.forEach(item => {
        this.updateTestItemWatcher(item.id)
        clear(item)
      })
    }
    clear(parentTest)
  }

  setTargetIdentifier(
    targetIdentifier: BuildTargetIdentifier,
    item: vscode.TestItem
  ) {
    const key = JSON.stringify(targetIdentifier)
    this.targetIdentifiers.set(key, item)
  }

  getTargetIdentifier(
    targetIdentifier: BuildTargetIdentifier
  ): vscode.TestItem | undefined {
    const key = JSON.stringify(targetIdentifier)
    return this.targetIdentifiers.get(key)
  }

  clearTargetIdentifiers() {
    this.targetIdentifiers.clear()
  }

  cacheBuildTargetsResult(result: bsp.WorkspaceBuildTargetsResult) {
    this.ctx.workspaceState.update(CONTEXT_KEY_TARGETS_RESULT, result)
  }

  getCachedBuildTargetsResult(): bsp.WorkspaceBuildTargetsResult | undefined {
    return this.ctx.workspaceState.get<bsp.WorkspaceBuildTargetsResult>(
      CONTEXT_KEY_TARGETS_RESULT
    )
  }

  cacheSourcesResult(params: bsp.SourcesParams, result: bsp.SourcesResult) {
    const key = JSON.stringify(params)
    const allResults =
      this.ctx.workspaceState.get<Record<string, bsp.SourcesResult>>(
        CONTEXT_KEY_SOURCES_RESULT
      ) || {}

    // Add or update the result for this params key
    allResults[key] = result
    this.ctx.workspaceState.update(CONTEXT_KEY_SOURCES_RESULT, allResults)
  }

  getCachedSourcesResult(
    params: bsp.SourcesParams
  ): bsp.SourcesResult | undefined {
    const key = JSON.stringify(params)
    const allResults = this.ctx.workspaceState.get<
      Record<string, bsp.SourcesResult>
    >(CONTEXT_KEY_SOURCES_RESULT)
    return allResults?.[key]
  }

  clearCache() {
    this.ctx.workspaceState.update(CONTEXT_KEY_TARGETS_RESULT, undefined)
    this.ctx.workspaceState.update(CONTEXT_KEY_SOURCES_RESULT, undefined)
  }
}

import * as vscode from 'vscode'
import {Inject, Injectable, OnModuleInit} from '@nestjs/common'
import path from 'path'

import {TestCaseStore} from './store'
import {BazelBSPBuildClient} from './client'
import {
  EXTENSION_CONTEXT_TOKEN,
  PRIMARY_OUTPUT_CHANNEL_TOKEN,
} from '../custom-providers'
import {BuildServerManager, CANCEL_ERROR_CODE} from '../server/server-manager'
import * as bsp from '../bsp/bsp'
import {
  SourceFileTestCaseInfo,
  TestCaseInfo,
  TestItemType,
} from '../test-info/test-info'
import {getExtensionSetting, SettingName} from '../utils/settings'
import {Utils} from '../utils/utils'
import {TestItemFactory} from '../test-info/test-item-factory'
import {
  DocumentTestItem,
  LanguageToolManager,
  TestFileContents,
} from '../language-tools/manager'
import {SyncHintDecorationsManager} from './decorator'

@Injectable()
export class TestResolver implements OnModuleInit, vscode.Disposable {
  @Inject(EXTENSION_CONTEXT_TOKEN) private readonly ctx: vscode.ExtensionContext
  @Inject(TestCaseStore) private readonly store: TestCaseStore
  @Inject(BazelBSPBuildClient) private readonly buildClient: BazelBSPBuildClient
  @Inject(BuildServerManager) private readonly buildServer: BuildServerManager
  @Inject(TestItemFactory) private readonly testItemFactory: TestItemFactory
  @Inject(LanguageToolManager)
  private readonly languageToolManager: LanguageToolManager
  @Inject(PRIMARY_OUTPUT_CHANNEL_TOKEN)
  private readonly outputChannel: vscode.OutputChannel
  @Inject(SyncHintDecorationsManager)
  private readonly syncHint: SyncHintDecorationsManager
  private repoRoot: string | null
  private openDocumentWatcherEnabled = false

  onModuleInit() {
    this.ctx.subscriptions.push(this)
    this.restorePriorTests()
      .catch(e => {
        this.outputChannel.appendLine(`Error restoring prior tests: ${e}`)
      })
      .finally(() => {
        this.registerHandlers()
      })
  }

  registerHandlers() {
    this.store.testController.resolveHandler = this.resolveHandler.bind(this)
    this.store.testController.refreshHandler = this.refreshHandler.bind(this)
  }

  private async restorePriorTests() {
    await this.resolveRoot()
    const cachedBuildTargetsResult = this.store.getCachedBuildTargetsResult()

    // Restore the root test item and build targets.
    let addedTargets = false
    if (cachedBuildTargetsResult) {
      this.outputChannel.appendLine('Restoring prior test cases')
      const root = this.store.testController.items.get('root')
      if (root) {
        try {
          this.outputChannel.appendLine('Restoring Source Files for Root')
          await this.processWorkspaceBuildTargetsResult(
            root,
            cachedBuildTargetsResult
          )
          root.canResolveChildren = false
          addedTargets = true
        } catch (e) {
          this.outputChannel.appendLine(
            `Error restoring source files for root: ${e}`
          )
        }
      }
    }

    // Restore cached source files for targets that have them.
    const promises: Promise<void>[] = []
    for (const [key, testItem] of this.store.targetIdentifiers.entries()) {
      let cachedSourceFiles: bsp.SourcesResult | undefined
      try {
        const target: bsp.BuildTargetIdentifier = JSON.parse(key)
        const sourceParams: bsp.SourcesParams = {
          targets: [target],
        }
        cachedSourceFiles = this.store.getCachedSourcesResult(sourceParams)
      } catch (e) {
        this.outputChannel.appendLine(
          `Invalid key '${key}' when restoring source files: ${e}`
        )
      }

      if (cachedSourceFiles) {
        this.outputChannel.appendLine(
          `Restoring source files for target: ${key}`
        )
        try {
          testItem.canResolveChildren = false
          const promise = this.processTargetSourcesResult(
            testItem,
            cachedSourceFiles
          )
          promises.push(promise)
        } catch (e) {
          this.outputChannel.appendLine(
            `Error restoring source files for target: ${key}`
          )
        }
      }
    }
    await Promise.all(promises)

    // Kick off discovery of test cases in other open files that may not have been discovered yet.
    if (addedTargets) await this.resolveOpenSourceFiles()
  }

  dispose() {}

  private async resolveHandler(
    parentTest: vscode.TestItem | undefined,
    testExplorerCancel?: vscode.CancellationToken
  ) {
    await vscode.window.withProgress(
      {
        location: vscode.ProgressLocation.Notification,
        title: 'Refreshing Test Cases',
        cancellable: true,
      },
      async (
        progress: vscode.Progress<{
          message?: string | undefined
          increment?: number | undefined
        }>,
        notificationCancel: vscode.CancellationToken
      ) => {
        progress.report({
          increment: -1,
          message:
            'Click [here](command:bazelbsp.showServerOutput) to check progress.',
        })
        const combinedToken = [REDACTED]
          testExplorerCancel,
          notificationCancel
        )
        if (parentTest === undefined) {
          try {
            await this.buildServer.getConnection()
          } catch (e) {
            this.outputChannel.appendLine(
              'Test explorer disabled due to lack of available build server.'
            )
          }

          return
        }

        // Wait for initialization before attempting requests to the server.
        updateDescription(
          parentTest,
          'Loading: waiting for build server initialization'
        )
        await this.buildClient.getInitializeResult()
        this.store.clearTestItemWatchers(parentTest)

        updateDescription(parentTest)
        const parentMetadata = this.store.testCaseMetadata.get(parentTest)

        switch (parentMetadata?.type) {
          case TestItemType.Root:
            progress.report({
              message:
                'Fetching test targets from build server ([progress](command:bazelbsp.showServerOutput))',
            })
            await this.resolveTargets(parentTest, combinedToken)
            await this.resolveOpenSourceFiles()
            break
          case TestItemType.BazelTarget:
            progress.report({
              message: `Fetching source files in ${parentMetadata.target?.displayName}`,
            })
            await this.resolveSourceFiles(parentTest, combinedToken)
            break
          case TestItemType.SourceFile:
            progress.report({
              message: `Finding test cases in ${parentMetadata.testItem.label}`,
            })
            await this.resolveDocumentTestCases(parentTest, combinedToken)
        }
      }
    )
  }

  /**
   * Refresh test items in the tree by kicking off the resolve handler at each root.
   * @param token Cancellation token tied to the refresh button on the VS Code UI.
   */
  private async refreshHandler(token: [REDACTED] {
    this.store.clearCache()
    const promises: Promise<void>[] = []
    this.store.testController.items.forEach(async item => {
      promises.push(this.resolveHandler(item, token))
    })
    await Promise.all(promises)
  }

  /**
   * Sets up a single root to hold all other test cases provided by this extension.
   * Selecting the root's file icon will navigate to the current project view file.
   */
  private async resolveRoot() {
    let projectViewUri: vscode.Uri | undefined = undefined
    const projectViewRelPath = getExtensionSetting(
      SettingName.BAZEL_PROJECT_FILE_PATH
    )

    this.repoRoot = await Utils.getWorkspaceGitRoot()
    if (projectViewRelPath && this.repoRoot) {
      const projectViewAbsPath = path.resolve(this.repoRoot, projectViewRelPath)
      projectViewUri = vscode.Uri.parse(projectViewAbsPath)
    }
    this.testItemFactory.createRootTestItem(projectViewUri)
  }

  /**
   * Gets available workspace targets from the build server, based on user's .bazelproject
   * If a target can be tested, it is added to the tree. Test items that no longer exist will be cleaned up.
   * @param parentTest TestItem to which newly found test items will be added (typically the root).
   */
  private async resolveTargets(
    parentTest: vscode.TestItem,
    cancellationToken?: vscode.CancellationToken
  ) {
    // Request available targets from the build server.
    updateDescription(
      parentTest,
      'Loading: waiting for build server connection'
    )
    parentTest.error = undefined
    const conn = await this.buildServer.getConnection()

    updateDescription(parentTest, 'Loading: fetching available targets')
    let result: bsp.WorkspaceBuildTargetsResult
    try {
      result = await conn.sendRequest(
        bsp.WorkspaceBuildTargets.type,
        cancellationToken
      )
      this.store.cacheBuildTargetsResult(result)
    } catch (e) {
      if (e.code === CANCEL_ERROR_CODE) {
        updateDescription(
          parentTest,
          'Refresh Canceled: Contents may be outdated.'
        )
        return
      }
      updateDescription(parentTest, 'Error: unable to fetch targets')
      throw e
    }
    await this.processWorkspaceBuildTargetsResult(parentTest, result)
  }

  private async processWorkspaceBuildTargetsResult(
    parentTest: vscode.TestItem,
    result: bsp.WorkspaceBuildTargetsResult
  ) {
    updateDescription(parentTest, 'Loading: processing target results')

    // Process the returned targets, create new test items, and store their metadata.
    const directories = new Map<string, vscode.TestItem>()
    const buildFileName = getExtensionSetting(SettingName.BUILD_FILE_NAME)
    parentTest.children.replace([])
    this.store.clearTargetIdentifiers()
    this.store.knownFiles.clear()

    result.targets.forEach(target => {
      if (!target.capabilities.canTest) return

      let relevantParent = parentTest
      if (target.baseDirectory) {
        const pathSegmentTestItems =
          this.testItemFactory.createPathSegmentTestItems(
            directories,
            target.baseDirectory
          )
        parentTest.children.add(pathSegmentTestItems.rootTestItem)
        relevantParent = pathSegmentTestItems.baseTestItem
      }

      const buildFileUri =
        target.baseDirectory && buildFileName
          ? vscode.Uri.parse(path.join(target.baseDirectory, buildFileName))
          : undefined
      // UI will group runs that have the same ID.
      const newTest = this.testItemFactory.createBuildTargetTestItem(
        target,
        buildFileUri
      )
      relevantParent.children.add(newTest)
      this.store.setTargetIdentifier(target.id, newTest)
    })

    // If no test items were added, show the getting started message as a test message overlaid on the .bazelproject file.
    // This provides an opportunity for the user to make adjustments and re-sync.
    if (parentTest.children.size === 0) {
      // Dummy test run that overlays the getting started message on the .bazelproject file.
      const run = this.store.testController.createTestRun(
        new vscode.TestRunRequest()
      )
      run.errored(parentTest, new vscode.TestMessage(gettingStartedMessage))
      run.end()

      // Link in the test explorer tree to set up the project.
      const encodedFileUri = encodeURIComponent(JSON.stringify(parentTest.uri))
      const syncFailMessage = new vscode.MarkdownString(
        `No test targets found. [Setup your project](command:vscode.open?${encodedFileUri})`
      )
      syncFailMessage.isTrusted = true
      parentTest.error = syncFailMessage
    }

    // Replace all children with the newly returned test cases.
    this.condenseTestItems(parentTest)
    updateDescription(parentTest)
  }

  /**
   * Kick off resolution of test items for files that are currently open, and watch for newly opened files.
   * This allows test cases to appear without the user having to expand the target's test explorer node.
   */
  private async resolveOpenSourceFiles() {
    const autoExpandTarget = getExtensionSetting(SettingName.AUTO_EXPAND_TARGET)
    // When disabled, tests are discovered as the test explorer tree is expanded.
    if (!autoExpandTarget) return

    for (const doc of vscode.workspace.textDocuments) {
      // Discovery within currently open documents.
      await this.expandTargetsForDocument(doc)
    }

    if (this.openDocumentWatcherEnabled) return
    this.openDocumentWatcherEnabled = true
    this.ctx.subscriptions.push(
      vscode.workspace.onDidOpenTextDocument(async doc => {
        // Discovery within newly opened documents.
        await this.expandTargetsForDocument(doc)
      })
    )
  }

  /**
   * Finds the corresponding target for a given document, if a file's target is not yet known.
   * The target's test cases will then be resolved and available in test explorer.
   * @param doc for which to find the target.
   */
  private async expandTargetsForDocument(doc: vscode.TextDocument) {
    if (doc.uri.scheme !== 'file') return

    // Avoid checking files that are already known, or not test files.
    if (this.store.knownFiles.has(doc.uri.toString())) return
    const tools = this.languageToolManager.getLanguageToolsForFile(doc)
    const docInfo = await tools.getDocumentTestCases(
      doc.uri,
      this.repoRoot ?? ''
    )
    if (!docInfo.isTestFile) return

    this.store.knownFiles.add(doc.uri.toString())
    const conn = await this.buildServer.getConnection()
    const params: bsp.InverseSourcesParams = {
      textDocument: {
        uri: doc.uri.toString(),
      },
    }
    let result: bsp.InverseSourcesResult | undefined
    await vscode.window.withProgress(
      {
        location: vscode.ProgressLocation.Notification,
        title: `Getting target for ${path.basename(doc.uri.fsPath)}.`,
        cancellable: true,
      },
      async (progress, token) => {
        try {
          result = await conn.sendRequest(
            bsp.BuildTargetInverseSources.type,
            params,
            token
          )
        } catch (e) {
          result = undefined
        }
      }
    )

    if (!result) {
      this.outputChannel.appendLine(
        `Unable to determine target for ${doc.fileName}.`
      )
      return
    }

    for (const target of result.targets) {
      // Put this file under the first matching target, in the rare event that a test is part of multiple targets.
      const targetItem = this.store.getTargetIdentifier(target)
      if (targetItem) {
        await this.resolveHandler(targetItem)
        return
      }
    }

    this.syncHint.enable(doc.uri, this.repoRoot ?? '', docInfo)
  }

  /**
   * Request source items for a target and populate within the tree.
   * @param parentTest TestItem to which newly found test items will be added.
   * @param cancellationToken Cancellation token to stop the request.
   */
  private async resolveSourceFiles(
    parentTest: vscode.TestItem,
    cancellationToken?: vscode.CancellationToken
  ) {
    const conn = await this.buildServer.getConnection()

    const parentMetadata: TestCaseInfo | undefined =
      this.store.testCaseMetadata.get(parentTest)
    if (!parentMetadata?.target) return

    const parentTarget = parentMetadata.target
    const params: bsp.SourcesParams = {
      targets: [parentTarget.id],
    }
    let result = await conn.sendRequest(
      bsp.BuildTargetSources.type,
      params,
      cancellationToken
    )

    const hasSources = result.items.some(item => item.sources.length > 0)
    const languageTools =
      this.languageToolManager.getLanguageTools(parentTarget)

    if (!hasSources && parentTarget.dependencies.length === 0) {
      const inferredResult = languageTools.inferSourcesFromTarget(
        parentTarget.id.uri,
        parentTarget.baseDirectory
      )
      if (inferredResult) {
        result = inferredResult
      }
    } else if (!hasSources && parentTarget.dependencies.length > 0) {
      const depParams: bsp.SourcesParams = {
        targets: parentTarget.dependencies,
      }
      result = await conn.sendRequest(
        bsp.BuildTargetSources.type,
        depParams,
        cancellationToken
      )
    }

    result.items.forEach(item => {
      item.sources = item.sources.filter(s =>
        languageTools.isValidTestSource(s.uri)
      )
    })
    const hasValidSources = result.items.some(item => item.sources.length > 0)

    if (!hasValidSources) {
      const inferredResult = languageTools.inferSourcesFromTarget(
        parentTarget.id.uri,
        parentTarget.baseDirectory
      )
      if (inferredResult) {
        result = inferredResult
      }
    }

    this.store.cacheSourcesResult(params, result)
    await this.processTargetSourcesResult(parentTest, result)
  }

  private async processTargetSourcesResult(
    parentTest: vscode.TestItem,
    result: bsp.SourcesResult,
    cancellationToken?: vscode.CancellationToken
  ) {
    const parentTarget = this.store.testCaseMetadata.get(parentTest)?.target
    if (!parentTarget) return

    const languageTools =
      this.languageToolManager.getLanguageTools(parentTarget)
    result.items.forEach(item => {
      item.sources = item.sources.filter(s =>
        languageTools.isValidTestSource(s.uri)
      )
    })
    const hasValidSources = result.items.some(item => item.sources.length > 0)

    if (!hasValidSources) {
      const inferredResult = languageTools.inferSourcesFromTarget(
        parentTarget.id.uri,
        parentTarget.baseDirectory
      )
      if (inferredResult) {
        result = inferredResult
      }
    }

    const directories = new Map<string, vscode.TestItem>()
    parentTest.children.replace([])
    parentTest.canResolveChildren = false
    const allDocumentTestItems: vscode.TestItem[] = []
    result.items.forEach(target => {
      target.sources.forEach(source => {
        // Parent to which the source file's test item will be added.
        // If the source file is in a subdirectory, the parent will be updated based on the path.
        let relevantParent = parentTest

        // If the current source is not in the target's base directory, create path segments.
        if (
          path.resolve(path.dirname(source.uri)) !==
          path.resolve(parentTarget.baseDirectory ?? '')
        ) {
          const pathSegmentTestItems =
            this.testItemFactory.createPathSegmentTestItems(
              directories,
              path.dirname(source.uri),
              parentTarget
            )
          parentTest.children.add(pathSegmentTestItems.rootTestItem)
          relevantParent = pathSegmentTestItems.baseTestItem
        }

        const newTest = this.testItemFactory.createSourceFileTestItem(
          parentTarget,
          source
        )
        this.store.knownFiles.add(source.uri)
        this.syncHint.disable(newTest.uri!)

        relevantParent.children.add(newTest)
        allDocumentTestItems.push(newTest)
      })
    })
    this.condenseTestItems(parentTest)

    // Kick off test case resolution within each of the target's documents.
    let counter = 1
    for (const doc of allDocumentTestItems) {
      updateDescription(
        parentTest,
        `Loading: analyzing test cases in file ${counter++} of ${
          allDocumentTestItems.length
        }`
      )
      await this.resolveDocumentTestCases(doc, cancellationToken)

      if (doc.uri) {
        // Assign a watcher to each source file's test item, to handle test case changes in the file.
        const watcher = vscode.workspace.createFileSystemWatcher(doc.uri.fsPath)
        watcher.onDidChange(e => {
          this.resolveHandler(doc)
        })
        this.store.updateTestItemWatcher(doc.id, watcher)
      }
    }
    updateDescription(parentTest)
  }

  private async resolveDocumentTestCases(
    parentTest: vscode.TestItem,
    cancellationToken?: vscode.CancellationToken
  ) {
    const parentTestInfo: SourceFileTestCaseInfo | undefined =
      this.store.testCaseMetadata.get(parentTest) as SourceFileTestCaseInfo
    if (!parentTestInfo?.target || parentTest.uri === undefined) return

    // Convert document contents into generic DocumentTestItem data.
    const testFileContents = await this.languageToolManager
      .getLanguageTools(parentTestInfo.target)
      .getDocumentTestCases(parentTest.uri, this.repoRoot ?? '')

    // If document analysis has determined that it is not to be considered a test file, hide it.
    if (!testFileContents.isTestFile) {
      // If removing this test item leaves the parent empty, clear the parent as well.
      const cleanupEmptyParent = (testItem?: vscode.TestItem) => {
        if (testItem?.children.size === 0) {
          const metadata = this.store.testCaseMetadata.get(testItem)
          const isTargetLevel = metadata?.type === TestItemType.BazelTarget
          if (isTargetLevel) {
            return
          }
          testItem.parent?.children.delete(testItem.id)
          cleanupEmptyParent(testItem.parent)
        }
      }

      parentTest.parent?.children.delete(parentTest.id)
      cleanupEmptyParent(parentTest.parent)
    }

    // Convert the returned test cases into TestItems and add to the tree.
    const newItems = new Map<DocumentTestItem, vscode.TestItem>()
    const directChildren: vscode.TestItem[] = []
    for (const testCase of testFileContents.testCases ?? []) {
      const newTest = this.testItemFactory.createTestCaseTestItem(
        testCase,
        parentTestInfo.target
      )
      newItems.set(testCase, newTest)

      // Maintain the same parent-child relationship as the returned test case data.
      if (testCase.parent) newItems.get(testCase.parent)?.children.add(newTest)
      else directChildren.push(newTest)
    }
    parentTest.children.replace(directChildren)

    // Update the parent test with required information for full-file run.
    if (testFileContents.documentTest)
      parentTestInfo.setDocumentTestItem(testFileContents.documentTest)
  }

  /**
   * Condense test items by removing unnecessary nesting.
   * All children below the parentTest containing only 1 child will be recursively condensed.
   * Applies only until the type of the parentTest is different from the type of the child.
   * @param parentTest Test below which to condense test items.
   */
  private condenseTestItems(parentTest: vscode.TestItem) {
    // Advance through any single-child test items of the same type.
    const getNextItem = (currentItem: vscode.TestItem): vscode.TestItem => {
      let shouldContinue = true
      while (currentItem.children.size === 1 && shouldContinue) {
        // TestItemCollection supports only forEach iteration.
        currentItem.children.forEach(childItem => {
          if (
            this.store.testCaseMetadata.get(currentItem)?.type !==
            this.store.testCaseMetadata.get(childItem)?.type
          ) {
            shouldContinue = false
            return
          }
          currentItem = childItem
        })
      }
      return currentItem
    }

    // Recursively filter the current item and its children, and update their label relative to the parent.
    const condense = (item: vscode.TestItem): vscode.TestItem => {
      let currentParent = getNextItem(item)

      currentParent.children.forEach(child => {
        const filteredChild = condense(child)
        this.store.testCaseMetadata
          .get(filteredChild)
          ?.setDisplayName(this.store.testCaseMetadata.get(currentParent))
        if (filteredChild !== child) {
          currentParent.children.delete(child.id)
          currentParent.children.add(filteredChild)
        }
      })
      return currentParent
    }
    return condense(parentTest)
  }
}

/**
 * Update or clear a test case description on the UI. Can be use to report activity and progress.
 * @param testItem Test item to be updated.
 * @param description New description. If omitted, will clear existing description.
 */
function updateDescription(testItem: vscode.TestItem, description?: string) {
  if (description) testItem.description = description
  else testItem.description = ''
}

function combineCancelTokens(
  token1: vscode.CancellationToken | undefined,
  token2: vscode.CancellationToken | undefined
): vscode.CancellationToken {
  const combinedSource = new vscode.CancellationTokenSource()
  token1?.onCancellationRequested(() => combinedSource.cancel())
  token2?.onCancellationRequested(() => combinedSource.cancel())
  return combinedSource.token
}

