    connectionDetailsParser = moduleRef.get(ConnectionDetailsParser)
  })

  afterEach(() => {
    sandbox.restore()
  })

  test('empty file', async () => {
    const paths = ['/path/1']
    sandbox.stub(Utils, 'readdir').resolves(paths)
    sandbox.stub(Utils, 'readFile').resolves('')
    const result = await connectionDetailsParser.getServerConnectionDetails(
      'sample',
      testDir
    )
    assert.equal(result, undefined)
  })

  test('not installed', async () => {
    const paths = ['/repo/root/.bsp/sample1.json']
    sandbox.stub(Utils, 'readdir').rejects(new Error('nonexistent dir'))
    const result = await connectionDetailsParser.getServerConnectionDetails(
      'sample',
      testDir
    )
    assert.equal(result, undefined)
  })

  const testCases = [
    {
      name: 'no match',
      expectedResultIndex: undefined,
      configs: [
        {
          name: 'other',
          version: '1.0',
          argv: ['/bin/path/', '--foo', '--bar'],
          languages: ['scala'],
          bspVersion: '2.0',
        },
      ],
    },
    {
      name: 'valid single entry',
      expectedResultIndex: 0,
      configs: [
        {
          name: 'sample',
          version: '1.0',
          argv: ['/bin/path/', '--foo', '--bar'],
          languages: ['scala'],
          bspVersion: '2.0',
        },
      ],
    },
    {
      name: 'multiple versions and build servers',
      expectedResultIndex: 1,
      configs: [
        {
          name: 'sample',
          version: '1.0.0',
          argv: ['/bin/path/', '--foo', '--bar'],
          languages: ['scala'],
          bspVersion: '2.0.0',
        },
        {
          name: 'sample',
          version: '1.1.1',
          argv: ['/bin/path/', '--foo', '--bar'],
          languages: ['scala'],
          bspVersion: '2.0.1',
        },
        {
          name: 'sample',
          version: '1.1.1-NIGHTLY',
          argv: ['/bin/path/', '--foo', '--bar'],
          languages: ['scala'],
          bspVersion: '2.0.1',
        },
        {
          name: 'other',
          version: '1.1.0',
          argv: ['/bin/path/', '--foo', '--bar'],
          languages: ['scala'],
          bspVersion: '2.0.0',
        },
      ],
    },
    {
      name: 'multiple servers, no match',
      expectedResultIndex: undefined,
      configs: [
        {
          name: 'other1',
          version: '1.0.0',
          argv: ['/bin/path/', '--foo', '--bar'],
          languages: ['scala'],
          bspVersion: '2.0.0',
        },
        {
          name: 'other2',
          version: '1.1.1',
          argv: ['/bin/path/', '--foo', '--bar'],
          languages: ['scala'],
          bspVersion: '2.0.1',
        },
        {
          name: 'other3',
          version: '1.1.1-NIGHTLY',
          argv: ['/bin/path/', '--foo', '--bar'],
          languages: ['scala'],
          bspVersion: '2.0.1',
        },
        {
          name: 'other4',
          version: '1.1.0',
          argv: ['/bin/path/', '--foo', '--bar'],
          languages: ['scala'],
          bspVersion: '2.0.0',
        },
      ],
    },
  ]

  for (const testCase of testCases) {
    test(testCase.name, async () => {
      const lookupMap: Map<string, string> = new Map()
      const fileNames = testCase.configs.map(config => {
        const currentPathBase = `${config.name + config.version}.json`
        const currentPathAbs = path.join(testDir, '.bsp', currentPathBase)
        lookupMap.set(currentPathAbs, JSON.stringify(config))
        return currentPathBase
      })

      sandbox.stub(Utils, 'readdir').resolves(fileNames)
      sandbox.stub(Utils, 'readFile').callsFake((path: string) => {
        return Promise.resolve(lookupMap.get(path) ?? '')
      })

      const result = await connectionDetailsParser.getServerConnectionDetails(
        'sample',
        testDir
      )
      if (testCase.expectedResultIndex === undefined) {
        assert.equal(result, undefined)
        return
      }
      assert.deepEqual(result, testCase.configs[testCase.expectedResultIndex])
    })
  }
})

import * as assert from 'assert'
import * as vscode from 'vscode'
import * as sinon from 'sinon'
import cp from 'child_process'
import {Test} from '@nestjs/testing'
import {beforeEach, afterEach} from 'mocha'
import * as rpc from 'vscode-jsonrpc'

import {
  PRIMARY_OUTPUT_CHANNEL_TOKEN,
  contextProviderFactory,
  outputChannelProvider,
} from '../../custom-providers'
import {BuildServerManager} from '../../server/server-manager'
import {createSampleMessageConnection} from './test-utils'
import {ConnectionDetailsParser} from '../../server/connection-details'
import {Utils} from '../../utils/utils'
import {BspConnectionDetails} from '../../bsp/bsp'
import * as settings from '../../utils/settings'

suite('Build Server', () => {
  let ctx: vscode.ExtensionContext
  let buildServer: BuildServerManager
  let spawnStub: sinon.SinonStub
  let sampleConn: rpc.MessageConnection
  let appendLineStub: sinon.SinonStub
  let outputChannel: vscode.LogOutputChannel
  let appendLinePromise: Thenable<void>

  const sandbox = sinon.createSandbox()

  beforeEach(async () => {
    let process = cp.spawn('echo hello; echo world >&2', {
      shell: true,
    })
    spawnStub = sandbox.stub(cp, 'spawn').returns(process)
    outputChannel = vscode.window.createOutputChannel('sample', {log: true})
    appendLinePromise = new Promise(resolve => {
      appendLineStub = sandbox
        .stub(outputChannel, 'appendLine')
        .callsFake(() => resolve())
    })

    sampleConn = createSampleMessageConnection()
    sandbox.stub(rpc, 'createMessageConnection').returns(sampleConn)
    sandbox.stub(Utils, 'getWorkspaceGitRoot').resolves('/sample/path')

    ctx = {
      subscriptions: [],
      workspaceState: {
        update: sandbox.stub(),
        get: sandbox.stub().resolves(undefined),
      },
    } as unknown as vscode.ExtensionContext
    const moduleRef = await Test.createTestingModule({
      providers: [contextProviderFactory(ctx), BuildServerManager],
    })
      .useMocker(token => {
        if (token === PRIMARY_OUTPUT_CHANNEL_TOKEN) {
          return outputChannel
        } else if (token === ConnectionDetailsParser) {
          return {
            getServerConnectionDetails: async (
              bspServerName: string,
              repoRoot: string
            ): Promise<BspConnectionDetails> => {
              return {
                name: bspServerName,
                argv: ['/bin/sample', 'arg1', 'arg2'],
                version: '1.0.0',
                bspVersion: '1.0.0',
                languages: [],
              }
            },
          }
        }
        throw new Error('No mock available for token.')
      })
      .compile()

    buildServer = moduleRef.get(BuildServerManager)
  })

  afterEach(() => {
    sandbox.restore()
    ctx.subscriptions.forEach(item => item.dispose())
  })

  test('OnModuleInit', async () => {
    sandbox.stub(settings, 'getExtensionSetting').returns('1.0.0')

    buildServer.onModuleInit()
    assert.equal(ctx.subscriptions.length, 1)
    const conn = await buildServer.getConnection()
    assert.ok(spawnStub.calledOnce)
    assert.ok(conn)
  })

  test('ServerLaunch', async () => {
    sandbox.stub(settings, 'getExtensionSetting').returns('1.0.0')

    const listenStub = sinon.stub(sampleConn, 'listen')

    buildServer.serverLaunch()
    const conn = await buildServer.getConnection()

    await appendLinePromise
    assert.ok(appendLineStub.calledOnce)
    assert.ok(spawnStub.calledOnce)
    assert.ok(listenStub.calledOnce)
    assert.ok(conn)
  })

  test('ServerLaunch, version upgrade', async () => {
    sandbox.stub(settings, 'getExtensionSetting').returns('1.0.1')
    const commandStub = sandbox
      .stub(vscode.commands, 'executeCommand')
      .resolves(true)

    const listenStub = sinon.stub(sampleConn, 'listen')

    buildServer.serverLaunch()
    const conn = await buildServer.getConnection()

    await appendLinePromise
    assert.ok(commandStub.calledOnceWith('bazelbsp.install'))
    assert.ok(appendLineStub.calledOnce)
    assert.ok(spawnStub.calledOnce)
    assert.ok(listenStub.calledOnce)
    assert.ok(conn)
  })

  test('Dispose', async () => {
    sandbox.stub(settings, 'getExtensionSetting').returns('1.0.0')

    buildServer.serverLaunch()
    const conn = await buildServer.getConnection()

    // Ensure that we have called dispose on the connection.
    let isDisposed = false
    conn.onDispose(() => {
      isDisposed = true
    })
    await buildServer.dispose()
    assert.ok(isDisposed)
  })
})

import * as assert from 'assert'
import {beforeEach} from 'mocha'
import {TaskEventTracker} from '../../test-runner/task-events'
import {
  StatusCode,
  TaskFinishDataKind,
  TaskStartDataKind,
  TestStatus,
} from '../../bsp/bsp'
import {TestFinishDataKind} from '../../bsp/bsp-ext'

suite('Task Events Tracker', () => {
  let tracker: TaskEventTracker

  beforeEach(async () => {
    tracker = new TaskEventTracker()
  })

  test('Get build target from task', async () => {
    for (let i = 0; i < sampleEvents.length; i++) {
      tracker.addTaskStart(sampleEvents[i].start)
    }

    for (let i = sampleEvents.length - 1; i >= 0; i--) {
      tracker.addTaskFinish(sampleEvents[i].finish)
    }

    // Accurately get the target from any subtasks.
    let result = tracker.getBuildTargetId('task2')
    assert.deepStrictEqual(result, {uri: 'sample'})

    result = tracker.getBuildTargetId('task1')
    assert.deepStrictEqual(result, {uri: 'sample'})
  })

  test('Retrieve existing event', async () => {
    for (let i = 0; i < sampleEvents.length; i++) {
      tracker.addTaskStart(sampleEvents[i].start)
    }

    for (let i = sampleEvents.length - 1; i >= 0; i--) {
      tracker.addTaskFinish(sampleEvents[i].finish)
    }

    let result = tracker.getTaskEvent('task2')
    assert.deepStrictEqual(result?.startParams, sampleEvents[1].start)
    assert.deepStrictEqual(result?.finishParams, sampleEvents[1].finish)

    result = tracker.getTaskEvent('task1')
    assert.deepStrictEqual(result?.startParams, sampleEvents[0].start)
    assert.deepStrictEqual(result?.finishParams, sampleEvents[0].finish)
  })
})

